INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1657', 'spa', 'Gosén — la fértil región del delta del Nilo donde Israel residió, y un distrito en el sur de Judá.', 'Gosén designa ante todo la exuberante zona oriental del delta de Egipto que José aseguró para la familia de su padre (Gn 45:10; 46:28-34; 47:1-6). Protegida de las plagas que azotaron al resto de Egipto (Éx 8:22; 9:26), se convirtió en símbolo de protección divina en medio del juicio. Un segundo Gosén aparece en la zona montañosa meridional de Judá, tanto como distrito conquistado por Josué (Jos 10:41; 11:16) como ciudad enumerada entre las asignaciones de Judá (Jos 15:51). Las principales traducciones conservan el nombre sin alteración: español «Gosén/Goshén», francés «Gosen», alemán «Goschen/Goshen».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1660', 'spa', 'Lagar, instalación o cuba para pisar uvas', 'El término hebreo estándar para el lagar, la instalación donde se pisaban las uvas para extraer su jugo. Aparece tanto en contextos literales como en poderosos usos figurados. Gedeón trilla trigo en un lagar para ocultarlo de Madián (Jue 6:11) y Nehemías observa la profanación del sábado junto a los lagares (Neh 13:15). En el ámbito profético, el lagar se convierte en símbolo del juicio divino: Isaías retrata a Dios pisando el lagar a solas con vestiduras teñidas de rojo (Is 63:2), Lamentaciones muestra al Señor pisando un lagar sobre Jerusalén (Lm 1:15) y Joel llama a los guerreros a pisar porque el lagar está lleno (Jl 3:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1661', 'spa', 'Gat (literalmente ''lagar'') es el nombre propio de una de las cinco ciudades-estado principales de los filisteos, que aparece 33 veces en la Biblia heb', 'Gat (literalmente ''lagar'') es el nombre propio de una de las cinco ciudades-estado principales de los filisteos, que aparece 33 veces en la Biblia hebrea. Fue hogar del remanente de los anaceos (Jos 11:22) y, sobre todo, de Goliat, ''el filisteo de Gat'' (1 S 17:4, 23). David huyó allí dos veces para escapar de Saúl, fingiendo locura ante el rey Aquis (1 S 21:10-15) y luego estableciéndose como vasallo en la cercana Siclag (1 S 27:2-4). El lamento de David por Saúl y Jonatán suplica ''No lo publiquéis en Gat'' (2 S 1:20), expresión que se volvió proverbial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1663', 'spa', 'Guitita — adjetivo gentilicio para un habitante de la ciudad filistea de Gat.', 'Guitita — adjetivo gentilicio para un habitante de la ciudad filistea de Gat.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1665', 'spa', 'La Guitit: término musical en títulos de salmos, posiblemente un instrumento o una melodía', 'Este sustantivo femenino aparece únicamente en los encabezados de los Salmos 8, 81 y 84 con la frase «sobre la Guitit» (עַל־הַגִּתִּית). Su significado es debatido. Las versiones antiguas sugieren: (1) una lira o instrumento musical de Gat, (2) una melodía asociada con la ciudad de Gat, o (3) un canto para la vendimia, si se lee como «lagares». El Targum favoreció la interpretación instrumental. Los eruditos modernos siguen divididos. Sea cual fuere su sentido exacto, funcionaba como indicación técnica musical para el coro levítico al interpretar estos salmos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1667', 'spa', 'Gat-rimón; ciudad levítica en el territorio de Dan, que significa «lagar de la granada».', 'Nombre compuesto que combina gat («lagar») y rimón («granada»), designando una ciudad levítica asignada a Dan. Aparece en la lista de ciudades danitas (Jos 19:45) y luego como ciudad entregada a los levitas coatitas (Jos 21:24; 1 Cr 6:69). La mención en Josué 21:25 dentro del territorio de Manasés es considerada por BDB como un error escribal por Ibleam. Todas las traducciones preservan de forma consistente la forma compuesta (Gat-Rimón), sin presentar ambigüedad semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1668', 'spa', 'esta, esa (pronombre demostrativo femenino arameo); en construcción recíproca, ''la otra''', 'Pronombre demostrativo femenino arameo, contraparte del masculino denah. Aparece exclusivamente en las secciones arameas de Daniel, señalando referentes contextualmente destacados: ''esta gran Babilonia'' (Dan 4:30), ''este cuerno'' (Dan 7:8) y las distintas bestias del capítulo 7. En un uso particular con la preposición lamed, forma una construcción recíproca: da leda, que significa ''una contra otra'' (Dan 5:6), describiendo las rodillas de Belsasar golpeándose entre sí de terror. En español, ''esta'' y ''este'' captan la fuerza demostrativa básica en todos los contextos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1669', 'spa', 'Languidecer, desfallecer: debilitarse por aflicción, pena o privación', 'Este verbo describe el estado de languidecer o desfallecer, ya sea física o emocionalmente. El Salmo 88:9 lo emplea para describir los ojos que se debilitan por la aflicción. Jeremías 31:12 promete que el Israel redimido «no volverá a languidecer», y 31:25 habla de saciar el alma desfallecida, aunque algunos interpretan esta última forma como adjetivo. El verbo aparece en contextos de angustia, hambre y dolor. Posiblemente se relaciona con raíces árabes que expresan cansancio y fatiga. La palabra capta la experiencia de perder las fuerzas vitales bajo el peso del sufrimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1672', 'spa', 'Estar ansioso, preocuparse, temer; experimentar angustia interior, inquietud o temor ante una situación o persona.', 'Describe un estado de preocupación ansiosa, inquietud o temor. En sus primeros usos (1 Sam 9:5; 10:2), el padre de Saúl se preocupa por su hijo desaparecido, una ansiedad paternal natural. La palabra también transmite pavor espiritual y existencial: el salmista se angustia a causa del pecado (Sal 38:18), y Jeremías 17:8 promete que quien confía en el SEÑOR no se inquietará ni en la sequía. Isaías 57:11 la emplea en paralelo con «temer», acercándose al sentido de tener pavor de otra persona. Emparentada con el talmúdico de''ig, la raíz captura consistentemente la turbación interior de la aprensión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1673', 'spa', 'Doeg: edomita al servicio de Saúl que delató a los sacerdotes de Nob y los masacró (1 Sam 22:18).', 'Doeg el edomita era el jefe de los pastores de Saúl y presenció cómo David recibió ayuda del sacerdote Ahimelec en Nob (1 Sam 21:7). Cuando Saúl exigió saber quién había auxiliado a David, Doeg delató a los sacerdotes y luego los ejecutó personalmente, matando a ochenta y cinco de ellos, dado que los propios soldados de Saúl se negaron a hacerlo (1 Sam 22:9, 18). Su traición queda conmemorada en el título del Salmo 52, donde David denuncia la jactancia del poderoso que ama el mal más que el bien. Doeg permanece en la narrativa bíblica como sinónimo de delación mortífera y violencia despiadada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1674', 'spa', 'ansiedad, preocupación; estado emocional turbado de inquietud temerosa o aprensión', 'Sustantivo femenino que denota ansiedad, preocupación inquieta o temor aprensivo. En la literatura sapiencial, Proverbios 12:25 enseña que ''la ansiedad en el corazón lo oprime'', usando esta palabra para la carga interior de la preocupación. En contextos proféticos, Ezequiel la empareja con ''espanto'' para describir el racionamiento temeroso de pan y agua durante el asedio de Jerusalén (Ez 4:16; 12:18-19). Jeremías la emplea para el pánico que se apodera de Damasco (Jer 49:23), mientras que Josué 22:24 expresa la preocupación de Israel ''por temor de'' un futuro malentendido entre las tribus.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1675', 'spa', 'Volar velozmente, lanzarse en picada; descenso rápido como el de un águila sobre su presa, usado en teofanía y juicio divino.', 'Un verbo vívido que describe el vuelo rápido y arrollador, el tipo de descenso aterrador que un águila ejecuta sobre su presa. En Deuteronomio 28:49 describe a una nación lejana que se lanza como águila sobre Israel desobediente, mientras que en Jeremías 48:40 y 49:22 la misma imagen del águila retrata el juicio divino extendiendo sus alas sobre Moab y Edom. De manera aún más impactante, el Salmo 18:10 lo emplea para describir a Dios mismo surcando los cielos sobre las alas del viento durante una teofanía. El verbo evoca consistentemente velocidad depredadora y poder abrumador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1677', 'spa', 'dob — oso; el oso pardo sirio, usado literalmente del animal y figuradamente para expresar ferocidad y peligro.', 'dob — oso; el oso pardo sirio, usado literalmente del animal y figuradamente para expresar ferocidad y peligro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1681', 'spa', 'Calumnia, infamia, difamación; murmuración maliciosa que daña la reputación o difunde un informe falso.', 'Este sustantivo hebreo capta el poder insidioso del habla destructiva, desde el cuchicheo a espaldas de alguien hasta un informe difamatorio en toda regla. En Génesis 37:2, el joven José trae un ''mal informe'' sobre sus hermanos, desencadenando el drama de celos y exilio. Los espías que desalentaron a Israel de entrar en Canaán difundieron una dibbah de la tierra (Nm 13:32; 14:36-37), y Jeremías escuchó la dibbah de muchos que murmuraban contra él (Jer 20:10). La palabra transmite un habla que se desliza sigilosamente, socavando la confianza e incitando al daño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1682', 'spa', 'Abeja; el insecto productor de miel, usado literal y figuradamente como símil de persecución hostil en enjambre.', 'La palabra hebrea común para designar a la abeja, presente tanto en el acertijo de Sansón como en la imaginería profética. En Jueces 14:8, un enjambre de abejas ha colonizado el cadáver de un león, dando origen al famoso acertijo. Deuteronomio 1:44 y Salmo 118:12 emplean las abejas como símil de enemigos que persiguen implacablemente en enjambre: los amorreos persiguieron a Israel «como hacen las abejas». Isaías 7:18 presenta a Dios silbando para llamar a la abeja que está en Asiria, una metáfora impactante para convocar a un ejército extranjero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1683', 'spa', 'Débora — nombre propio hebreo (''abeja''), llevado por la nodriza de Rebeca y por la profetisa y jueza de Israel.', 'Débora — nombre propio hebreo (''abeja''), llevado por la nodriza de Rebeca y por la profetisa y jueza de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1687', 'spa', 'El santuario interior o Lugar Santísimo: la cámara más interna del Templo de Salomón que albergaba el arca. Término arquitectónico técnico para la hab', 'El santuario interior o Lugar Santísimo: la cámara más interna del Templo de Salomón que albergaba el arca. Término arquitectónico técnico para la habitación más recóndita del Templo de Salomón, sinónimo del Lugar Santísimo (קֹדֶשׁ הַקֳּדָשִׁים). Etimológicamente relacionado con el árabe dubur (''parte trasera''), designa la cámara detrás de la nave principal donde residían el Arca de la Alianza y los querubines, la sala del trono de YHWH. Casi todas las dieciséis apariciones se concentran en el relato detallado de la construcción de 1 Reyes 6-7, describiendo sus dimensiones cúbicas, su revestimiento de oro y las grandes puertas de madera de olivo (1 Re 6:5, 16, 19-23, 31). La traducción ''oráculo'' en la KJV/RV refleja una derivación antigua pero incorrecta de דִּבֵּר (''hablar''); las traducciones modernas lo vierten uniformemente como ''santuario interior.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1688a', 'spa', 'Debir — ciudad real cananea en las tierras altas de Judá, antiguamente llamada Quiriat-séfer (''ciudad del libro'').', 'Topónimo que identifica una ciudad real cananea en las tierras altas meridionales de Judá, cerca de Hebrón, anteriormente conocida como Quiriat-séfer (''ciudad del libro'') y Quiriat-saná. Su conquista se narra dos veces: primero por Josué en la campaña del sur (Jos 10:38-39; 11:21) y luego por Otoniel hijo de Quenaz, quien gana a Acsa, hija de Caleb, como premio por capturarla (Jos 15:15-17; Jue 1:11-13). Debir aparece después entre las ciudades levíticas asignadas a los sacerdotes aaronitas (Jos 21:15; 1 Cr 6:43). Todas las traducciones conservan el nombre sin cambios: Debir en inglés, español, francés y alemán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1690', 'spa', 'Torta o masa de higos secos prensados', 'Término específico para una torta comprimida de higos secos, un alimento de provisión importante en el antiguo Israel. Estas tortas de higos servían tanto como raciones de viaje como de cataplasma medicinal. Abigail empacó doscientas tortas de higos entre las provisiones para los hombres de David (1 S 25:18), y a un esclavo egipcio agotado se le dio un trozo de torta de higos para restituir sus fuerzas (1 S 30:12). En una célebre aplicación terapéutica, Isaías prescribió una cataplasma de torta de higos para el divieso del rey Ezequías (2 R 20:7; Is 38:21). El equivalente griego παλάθη y el arameo debilta confirman el prensado de higos como tecnología alimentaria extendida por todo el Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1692', 'spa', 'Adherirse, aferrarse, pegarse; de devoción personal, adhesión física, persecución cercana y unión causativa. דָּבַק es uno de los verbos más táctiles ', 'Adherirse, aferrarse, pegarse; de devoción personal, adhesión física, persecución cercana y unión causativa. דָּבַק es uno de los verbos más táctiles y emocionalmente evocadores de la Biblia hebrea. En su núcleo físico, describe cosas que se pegan entre sí — la lengua al paladar, la piel a los huesos, las escamas del Leviatán firmemente trabadas. Pero su poder teológico proviene de su extensión relacional: el hombre se ''une'' a su esposa (Gn 2:24), Rut se ''aferra'' a Noemí (Rut 1:14) e Israel recibe el mandato de ''apegarse'' a Yahvé (Dt 10:20; 11:22; 13:4). El mismo verbo que describe una enfermedad adhiriéndose a la piel describe la lealtad del pacto adhiriéndose a Dios. La raíz árabe dabiq conserva el núcleo adhesivo, mientras que el coreano capta la dimensión relacional con 붙좇다 (''seguir de cerca, apegado'') y la dimensión física con 달라붙다 (''pegarse firmemente''). El tronco Hifil se bifurca en dos direcciones distintas: perseguir a alguien en batalla y hacer que algo se pegue — reflejando cómo la misma energía causativa puede dirigirse hacia personas (persecución) u objetos (adhesión).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1694', 'spa', 'Juntura, soldadura: el punto donde se unen o conectan las piezas', 'Este sustantivo se refiere a junturas, uniones o puntos de conexión. Isaías 41:7 lo emplea para la soldadura que sujeta las piezas de un ídolo. En 1 Reyes 22:34 y 2 Crónicas 18:33, describe las «junturas» de la armadura de Acab, es decir, la zona vulnerable entre la coraza y la armadura inferior donde una flecha lo hirió de muerte. La palabra deriva de דָּבַק («adherirse, pegarse»). Designa puntos críticos de conexión donde piezas separadas se unen, ya sea en trabajo de metalistería o en armadura protectora. El contexto de la armadura resalta que incluso las defensas bien unidas tienen costuras vulnerables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1695', 'spa', 'Adherido, unido: que se aferra estrechamente a alguien o algo', 'Este adjetivo describe a algo o alguien que se adhiere o se aferra estrechamente. Deuteronomio 4:4 habla de Israel como «los que se aferran» (הַדְּבֵקִים בַּ) a Yahvé, todos con vida. 2 Crónicas 3:12 describe el ala de un querubín «unida» (דְּבֵקָה לְ) a otra ala en el templo. Proverbios 18:24 habla de un amigo que «se une más» (אֹהֵב דָּבֵק) que un hermano. La palabra deriva de דָּבַק («adherirse, pegarse, unirse») y enfatiza un apego íntimo y persistente, ya sea pactal (a Dios), estructural (alas que se tocan) o relacional (amistad leal).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1696', 'spa', 'hablar, decir, declarar; (Qal ptc.) el que habla; (Hifil) someter; (Pual) ser dicho; (Hifil) destruir', 'Uno de los verbos más frecuentes de la Biblia hebrea, דָּבַר en su tronco dominante Piel significa hablar, decir, contar o declarar, con más de mil apariciones. La fórmula «y habló el SEÑOR a Moisés» (וַיְדַבֵּר יְהוָה אֶל־מֹשֶׁה) resuena a lo largo de toda la Torá. Una raíz homónima distinta, דבר II, aparece en el Hifil con el sorprendente sentido de «someter» (Sal 18:47; 47:3), probablemente relacionada con el árabe دَبَرَ «empujar por detrás». El Pual pasivo («ser dicho», Sal 87:3) y un raro sentido destructivo (2 Cr 22:10) completan el abanico semántico de este verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1697', 'spa', 'Palabra, discurso, asunto, cosa, suceso; sustantivo hebreo que une el enunciado hablado con la realidad objetiva', 'Pocos vocablos hebreos revelan tanto sobre el pensamiento israelita antiguo como דָּבָר. Con cerca de 1.500 apariciones, este sustantivo enlaza sin fisura lo que en español se separa entre «palabra» y «cosa», pues en la mentalidad hebrea la palabra pronunciada no es mero sonido, sino realidad sustantiva con fuerza y consecuencia. El דָּבָר de Dios crea, manda y juzga; el דָּבָר del profeta es simultáneamente mensaje y acontecimiento. El plural דְּבָרִים puede significar «palabras», «hechos», «asuntos» o «crónicas» según el contexto, lo que convierte a este sustantivo en columna vertebral del discurso narrativo y legal bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1698', 'spa', 'Pestilencia, plaga — enfermedad epidémica mortal, generalmente enviada o amenazada como juicio divino. דֶּבֶר es la palabra de la Biblia hebrea para l', 'Pestilencia, plaga — enfermedad epidémica mortal, generalmente enviada o amenazada como juicio divino. דֶּבֶר es la palabra de la Biblia hebrea para la epidemia catastrófica, y aparece 49 veces como uno de los instrumentos más temidos de aplicación del pacto por parte de Dios. Forma una tríada aterradora con la espada y el hambre — una fórmula repetida más de dieciséis veces solo en Jeremías (Jer 14:12; 21:7, 9) y reiterada a lo largo de Ezequiel (5:12; 6:11). La palabra aparece por primera vez en la advertencia de Moisés al faraón (Éx 5:3; 9:15), y luego puntúa las narrativas del desierto (Nm 14:12) y las maldiciones deuteronómicas (Dt 28:21). La elección de David de tres días de pestilencia sobre el hambre o la derrota militar (2 S 24:13-15) resultó en setenta mil muertes, haciendo del דֶּבֶר el evento más mortífero de su reinado. El cognado árabe dabr (''partida, muerte'') ilumina la conexión etimológica entre plaga y perecer. Todas las lenguas testigo lo traducen con severidad equivalente: español ''pestilencia'', francés ''peste'', alemán ''Pest''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1700', 'spa', 'causa, razón, orden, manera; a causa de, por orden de', 'Sustantivo femenino empleado casi exclusivamente en estado constructo o con preposiciones, que abarca las ideas de causa, razón u orden establecido. Su aparición más célebre se halla en el Salmo 110:4, donde Dios jura que el rey mesiánico es sacerdote para siempre עַל־דִּבְרָתִי מַלְכִּי־צֶדֶק (''según el orden de Melquisedec''), frase que se volvió fundamental tanto en la teología judía como en la cristiana (cf. Heb 7). En Eclesiastés funciona como preposición causal con el sentido de ''a causa de'' o ''por motivo de'' (3:18; 7:14; 8:2). En Job 5:8 Elifaz la usa con el significado de ''mi causa'' o ''mi caso''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1705', 'spa', 'Daberat: ciudad levítica en Isacar, al pie del monte Tabor', 'Daberat (también escrita Daberath o Dovrat) era una ciudad levítica asignada a la tribu de Isacar, situada al pie del monte Tabor. Aparece en las descripciones de límites de Josué (Jos 19:12, con artículo definido) y en las listas de ciudades levíticas (Jos 21:28; 1 Cr 6:72). Los estudiosos modernos la identifican con Deburije, un pueblo que aún se encuentra al pie del Tabor. Su etimología es incierta. Como ciudad levítica, albergaba sacerdotes y servía como centro de culto y enseñanza dentro del territorio de Isacar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1706', 'spa', 'Miel — la sustancia dulce producida por las abejas, también usada para el jarabe de frutas y como figura de dulzura. דְּבַשׁ abarca tanto la miel de a', 'Miel — la sustancia dulce producida por las abejas, también usada para el jarabe de frutas y como figura de dulzura. דְּבַשׁ abarca tanto la miel de abeja como, por extensión, el jarabe espeso extraído de dátiles u otras frutas — un doble sentido conocido en todas las lenguas semíticas (el árabe dibs significa específicamente miel de dátil). Sus 54 apariciones se entrelazan con algunas de las imágenes más vívidas de la Escritura: el acertijo de Sansón sobre la miel en el cadáver del león (Jue 14:8-18), la repetida fórmula del pacto ''tierra que fluye leche y miel'' (Éx 3:8), y la declaración del salmista de que las palabras de Dios son más dulces que la miel (Sal 19:10; 119:103). Los ojos de Jonatán se iluminan tras probar miel silvestre en el campo de batalla (1 S 14:27-29). Las traducciones convergen con precisión: español ''miel'', francés ''miel'', alemán ''Honig'' — ninguna distingue entre miel de abeja y jarabe de fruta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1709', 'spa', 'Pez: criatura acuática, usado colectiva o singularmente para peces de mar, río o cualquier cuerpo de agua. דָּג es la palabra hebrea estándar para pez', 'Pez: criatura acuática, usado colectiva o singularmente para peces de mar, río o cualquier cuerpo de agua. דָּג es la palabra hebrea estándar para pez, apareciendo tanto como singular (''un gran pez,'' Jon 2:1) como colectivo o plural (דָּגִים, דְּגֵי). En el orden de la creación, los peces del mar se ubican junto a las bestias y las aves como las tres categorías de vida animal sobre las cuales la humanidad ejerce dominio (Gén 9:2; Sal 8:9). La sabiduría de Salomón abarcaba discursos sobre los peces (1 Re 4:33), y Nehemías menciona la Puerta del Pescado y los mercaderes de pescado tirios (Neh 3:3; 13:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1710', 'spa', 'Pez (sustantivo femenino colectivo) — criaturas acuáticas como clase, especialmente del mar y del Nilo.', 'Este sustantivo femenino colectivo para pez se sitúa junto al más común masculino דָּג, pero porta una fuerza marcadamente colectiva, de clase. Aparece en el inicio mismo de las Escrituras cuando Dios otorga al ser humano dominio sobre «los peces del mar» (Gn 1:26, 28). Resurge en las plagas del Éxodo cuando mueren los peces del Nilo (Éx 7:18, 21), en la memoria nostálgica de Israel del pescado comido libremente en Egipto (Nm 11:5) y en el río escatológico de Ezequiel cuyas aguas rebosan de peces «de muchas especies» (Ez 47:9-10). La prohibición en Deuteronomio de ídolos con forma de pez (Dt 4:18) muestra cuán cargada teológicamente podía volverse incluso esta humilde palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1712', 'spa', 'Dagón — la deidad principal y el ídolo de los filisteos, venerado especialmente en Asdod y Gaza.', 'Nombre propio de la deidad nacional filistea, cuyo centro de culto estaba en Asdod (con un santuario secundario en Gaza). El relato dramático de 1 Samuel 5 concentra la mayoría de las ocurrencias: el arca capturada de Dios es colocada en el templo de Dagón, y el ídolo aparece postrado ante ella, primero intacto y luego con la cabeza y las manos desprendidas sobre el umbral (1 S 5:2-5). Este incidente origina la práctica cultual de no pisar el umbral de Dagón. El acto final de Sansón tiene lugar en un templo de Dagón en Gaza (Jue 16:23). La etimología podría vincularse al hebreo דָּג (''pez'') o a la deidad semítica del grano Dagán, aunque el origen sigue siendo debatido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1713b', 'spa', 'Enarbolar estandartes, estar abanderado: desplegar insignias militares en formación de batalla', 'Este verbo denominativo deriva de דֶּגֶל (''estandarte, bandera'') y significa enarbolar o desplegar estandartes. El Salmo 20:5 expresa la esperanza «enarbolaremos nuestras banderas» en el nombre de Dios, una imagen militar de concentración y triunfo. Cantares 6:4 y 6:10 describen a la amada como «abanderada» o «imponente como ejércitos con banderas». El verbo transmite organización militar, reunión en torno a insignias y el despliegue impresionante de fuerzas ordenadas. Algunas versiones antiguas leen verbos distintos, lo que sugiere cierta incertidumbre textual, pero la imagen de estandartes encaja bien en ambos contextos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1714', 'spa', 'Estandarte tribal o militar que marcaba las divisiones del campamento israelita y el orden de marcha en el desierto.', 'Se refiere a los grandes estandartes portados por cada una de las cuatro divisiones de tres tribus durante el campamento y la marcha de Israel en el desierto. Casi todas las 14 ocurrencias aparecen en Números 1-2 y 10, donde cada דֶּגֶל encabeza un campamento de tres tribus: Judá al este, Rubén al sur, Efraín al oeste, Dan al norte. El único uso figurado en Cantares 2:4 —«su bandera sobre mí es amor»— transforma el emblema militar en una imagen íntima de protección pactual. El español emplea consistentemente «bandera», mientras que el inglés alterna entre «banner» y «standard».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1715', 'spa', 'דָּגָן es un sustantivo masculino para el grano o los cultivos de cereal, que aparece 40 veces y se refiere consistentemente a productos cultivados — ', 'דָּגָן es un sustantivo masculino para el grano o los cultivos de cereal, que aparece 40 veces y se refiere consistentemente a productos cultivados — trigo, cebada y cultivos similares — sin designar una variedad específica. Su uso más característico es en la tríada formularia דָּגָן, תִּירוֹשׁ y יִצְהָר (''grano, mosto y aceite''), que se repite en Deuteronomio (7:13; 11:14; 12:17; 14:23; 18:4; 28:51), los profetas (Os 2:8-9, 22; Jl 1:10; 2:19) y Nehemías (5:11; 10:39; 13:5, 12). Esta tríada representa la abundancia agrícola completa de la tierra: el sustento de vida, el fruto de la vid y el producto del olivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1717', 'spa', 'Pecho, seno, pezón; el pecho femenino, usado en contextos eróticos y alegóricos.', 'Un término para el pecho femenino o pezón que aparece en contextos íntimos y alegóricos. Proverbios 5:19 lo emplea en el marco del amor conyugal —«que sus pechos te satisfagan en todo tiempo»— donde la palabra transmite calidez y ternura. Ezequiel 23:3, 8 y 21 lo despliega en la impactante alegoría de Aholá y Aholibá, donde la opresión de los pechos simboliza las relaciones infieles de Israel y Judá con potencias extranjeras. Se distingue del más común שַׁד por su registro más íntimo, incluso infantil, como señala BDB al notar su origen como «palabra primitiva de caricia».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1719a', 'spa', 'Dedán — un pueblo y región comercial en Arabia, descendiente de Cus (o de Abraham a través de Cetura).', 'Dedán — un pueblo y región comercial en Arabia, descendiente de Cus (o de Abraham a través de Cetura).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1722', 'spa', 'Oro (arameo); el metal precioso, usado en Daniel y Esdras para vasos de oro, estatuas y ornamentación real.', 'Oro (arameo); el metal precioso, usado en Daniel y Esdras para vasos de oro, estatuas y ornamentación real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1730', 'spa', 'Amado o amante (especialmente en el Cantar de los Cantares); un tío paterno; amor o caricias como sustantivo abstracto. דּוֹד es una de esas palabras ', 'Amado o amante (especialmente en el Cantar de los Cantares); un tío paterno; amor o caricias como sustantivo abstracto. דּוֹד es una de esas palabras hebreas cuyo rango semántico abarca lo íntimamente personal y lo sólidamente familiar. En el Cantar de los Cantares es la palabra emblemática de la mujer para su amante — ''mi amado'' (dodí) — y se repite más de veinticinco veces con una intensidad que encuentra ecos en el árabe habib y el hindi preetam. Sin embargo, la misma raíz designa al hermano del padre en textos legales como Levítico, donde el hindi lo traduce como chacha y el suajili como mjomba, términos de parentesco sin connotación romántica alguna. En su tercera acepción, el plural dodim se convierte en sustantivo abstracto para amor o caricias, como en Proverbios 7:18 y Cantar 1:2.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1731', 'spa', 'Olla o caldero para cocinar, o cesta para transportar productos como higos; el contexto determina cuál recipiente se indica.', 'Según el contexto, este sustantivo designa bien una olla de cocinar, bien una cesta para transportar. Como recipiente de cocina, aparece junto a sinónimos como parur y qallachath en el relato de la práctica sacrificial sacerdotal en Silo (1 Sam 2:14) y los preparativos de la Pascua bajo Josías (2 Cr 35:13). Como cesta, destaca en la visión de Jeremías de dos cestas de higos puestas ante el templo (Jer 24:1-2) y en el detalle macabro de cabezas cortadas transportadas en canastas (2 Re 10:7). Las tradiciones española e inglesa distinguen consistentemente ambos sentidos: «caldero/kettle» frente a «cesta/basket».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1732', 'spa', 'David — segundo y mayor rey de Israel, hijo de Isaí, ancestro del Mesías', 'David (דָּוִד) es el nombre propio del rey paradigmático de Israel, el pastorcillo de Belén ungido por Samuel (1 S 16:13) que unificó las tribus, conquistó Jerusalén y recibió la promesa dinástica de un trono eterno (2 S 7:12-16). Posiblemente significando «el amado», el nombre aparece 1.075 veces en Rut, Samuel, Reyes, Crónicas, los Salmos y los Profetas, testimonio del papel descomunal de David en la teología bíblica. La grafía alterna entre דָּוִד (libros anteriores) y דָּוִיד (libros posteriores, Crónicas), sin distinción semántica alguna. Todas las lenguas preservan el nombre sin cambio: David en español, francés, alemán e inglés por igual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1733', 'spa', 'Tía: la hermana del padre o la esposa del hermano del padre', 'Este sustantivo femenino designa a la tía dentro de la línea paterna. Éxodo 6:20 relata que Amram se casó con su tía Jocabed (hermana de su padre), madre de Moisés y Aarón. Levítico 18:14 y 20:20 prohíben las relaciones sexuales con la tía (esposa del hermano del padre). La palabra deriva de דּוֹד (''tío, amado'') y señala parentescas femeninas de la línea paterna. Estas leyes reflejan las prohibiciones de incesto de Israel, definiendo los grados de consanguinidad dentro de los cuales el matrimonio y las relaciones sexuales estaban vedados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1734', 'spa', 'Dodo; nombre propio hebreo que significa ''su amado'', llevado por varios hombres en la época de los jueces y de David', 'Nombre propio masculino que significa ''su amado'' o posiblemente relacionado con un epíteto divino. Lo llevan al menos tres individuos: el abuelo del juez Tolá, de la tribu de Isacar (Jue 10:1); el padre de Eleazar, uno de los tres valientes de David (2 Sam 23:9; 1 Cr 11:12); y el padre de Elhanán, otro de los guerreros de David (2 Sam 23:24; 1 Cr 11:26). La variación ketiv-qere entre דֹּדִי y דּוֹדוֹ en 2 Samuel 23:9 refleja la transmisión escribal de este nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1736', 'spa', 'Mandrágoras — fruto aromático de Mandragora officinarum, asociado con la fertilidad y el deseo; una vez usado como «cestas» en Jer 24:1.', 'Se refiere casi siempre a la mandrágora (Mandragora officinarum), cuyo fruto carnoso y fragante era apreciado en el antiguo Cercano Oriente como afrodisíaco y promotor de la fertilidad. La palabra entra en la narrativa bíblica de manera memorable en Génesis 30:14-16, donde Rubén halla mandrágoras durante la cosecha de trigo y Raquel negocia con Lea por ellas, esperando que la ayuden a concebir. Cantares 7:14 celebra su embriagadora fragancia. El alemán «Liebesapfel» (manzana de amor) captura hermosamente la creencia popular que subyace al hebreo. Una aparición en Jeremías 24:1 parece ser una forma homógrafa que significa «cestas», probablemente de una raíz distinta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1739', 'spa', 'desfallecido, enfermo, débil; menstruante, en estado de impureza menstrual', 'Adjetivo que describe un estado de debilidad física, enfermedad o impureza ritual por menstruación. En Lamentaciones transmite un profundo desfallecimiento emocional y espiritual: el corazón de Jerusalén desfallece (1:13) y los ojos de Sion se oscurecen (5:17). En las leyes de pureza levítica, la forma femenina designa a la mujer durante la menstruación (Lv 15:33; 20:18). Isaías 30:22 lo emplea metafóricamente, comparando el rechazo de los ídolos con desechar algo inmundo. La convergencia de debilidad corporal e impureza ritual en un solo término refleja la visión holística hebrea de la integridad física y espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1740', 'spa', 'enjuagar, lavar, limpiar mediante enjuague; figuradamente, lavar la culpa', 'Verbo en la conjugación Hifil que significa enjuagar o limpiar mediante lavado, empleado tanto para la purificación ritual como para la limpieza moral figurada. En el contexto del templo, las víctimas sacrificiales se enjuagaban en las pilas antes de la ofrenda (Ez 40:38; 2 Cr 4:6). Isaías 4:4 eleva la imagen para describir a Dios lavando la inmundicia y las manchas de sangre de las hijas de Jerusalén mediante un espíritu de juicio y de fuego. El cognado arameo en Afel confirma el sentido causativo de ''hacer que sea lavado''. En Jer 51:34 la lectura Qere redirige a נָדָה (expulsar), una raíz distinta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1742', 'spa', 'Desfalleciente: describe un corazón enfermo de pena, dolor o angustia', 'Este adjetivo describe un corazón que ha desfallecido o enfermado a causa de la angustia. Isaías 1:5 pregunta por qué Israel persiste en la rebelión cuando todo el corazón está «desfalleciente» (דַּוָּי). Jeremías 8:18 lamenta «mi corazón desfallece dentro de mí» ante la calamidad del pueblo. Lamentaciones 1:22 habla de suspirar con un corazón desfalleciente. La palabra aparece exclusivamente junto a ''corazón'' (לֵב), señalando agotamiento emocional y espiritual más que simple debilidad física. Captura la pesada sensación de un corazón abrumado por el duelo prolongado o el peso del pecado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1746', 'spa', 'Dumá; hijo de Ismael, ciudad de Judá, y nombre críptico para Edom que significa ''silencio''.', 'Un nombre propio con tres referentes distintos unidos por el hilo del silencio y la desolación. Primero, Dumá es un hijo de Ismael (Gn 25:14; 1 Cr 1:30), probablemente vinculado al oasis de Dumat al-Yandal en el norte de Arabia. Segundo, designa una ciudad en la región montañosa de Judá (Jos 15:52), identificada con la moderna Daume al suroeste de Hebrón. Tercero, y de manera más evocadora, Isaías 21:11 usa Dumá como designación críptica de Edom, jugando con el significado hebreo de ''silencio'', un juego de palabras profético que sugiere la quietud mortal que aguarda a esa nación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1747', 'spa', 'Silencio, espera quieta, quietud; reposo contemplativo del alma ante Dios.', 'Un término profundamente devocional que describe la quietud silenciosa y confiada del alma ante Dios. En el Salmo 62:1, el salmista declara «solo en Dios mi alma espera en silencio», una postura de confianza radical. El Salmo 65:1 empareja el silencio con la alabanza, sugiriendo que a veces la adoración más apropiada es la reverente quietud. El Salmo 39:2 capta un matiz diferente, donde el silencio se convierte en dolorosa contención frente a los impíos. Y el Salmo 22:2 lo usa para la angustiosa ausencia de descanso. El núcleo contemplativo de esta palabra resuena en todas las tradiciones de espiritualidad bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1748', 'spa', 'Silencio, en silencio: permanecer callado, ya sea en sumisión o en asombro mudo', 'Este sustantivo y adverbio denotan silencio o el estado de estar callado. Isaías 47:5 ordena a Babilonia sentarse «en silencio» (דוּמָם) en humillación. Lamentaciones 3:26 afirma que es bueno esperar «en silencio» (וְדוּמָם) la salvación de Dios. Habacuc 2:19 se burla del ídolo llamándolo «piedra de silencio» (אֶבֶן דוּמָם), completamente mudo, incapaz de hablar. La palabra deriva de דָּמַם (''callar, estar quieto'') y puede indicar silencio impuesto (la vergüenza de Babilonia), espera paciente (perseverancia fiel) o la mudez esencial de objetos sin vida (la impotencia del ídolo).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1749', 'spa', 'Cera; sustancia blanda y fundible usada exclusivamente en símiles de derretimiento ante el poder o fuego de Dios.', 'Todas las apariciones de esta palabra en la Biblia hebrea se dan en símiles de derretimiento, lo que la convierte en uno de los sustantivos más consistentemente figurativos del Antiguo Testamento. Los montes se derriten como cera ante la presencia de Dios (Sal 97:5), los impíos perecen como cera ante el fuego (Sal 68:2), los collados fluyen como cera en la teofanía (Miq 1:4) y el corazón del salmista se derrite como cera en su angustia (Sal 22:14). La palabra nunca aparece en un contexto literal: existe en las Escrituras únicamente como la imagen por excelencia de lo que se disuelve ante un poder abrumador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1751', 'spa', 'ser triturado, quebrantado, desmenuzarse; verbo arameo que describe destrucción violenta', 'Este verbo arameo aparece en las visiones de Daniel para describir reinos aplastados por piedras o bestias que pisotean cuanto encuentran a su paso. Su vocabulario encaja en la imaginería apocalíptica: imperios completamente destrozados, reducidos a fragmentos. Aparecen tanto formas pasivas (ser triturado) como causativas activas (triturar a otros), pintando cuadros de destrucción total. La estatua de la historia humana en Daniel es pulverizada por una piedra divina; bestias sucesivas devoran y despedazan. La violencia del término subraya la naturaleza exhaustiva del juicio divino contra los poderes terrenales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1753', 'spa', 'Verbo arameo que significa ''habitar, residir''; también usado como participio sustantivado, ''moradores, habitantes''.', 'Verbo arameo que significa «habitar» o «vivir (en un lugar)», presente exclusivamente en Daniel. Aparece en formas finitas que describen a los animales habitando bajo la sombra de un gran árbol (Dn 4:9, 18) y como participio sustantivado con el significado de «moradores» o «habitantes», típicamente en la majestuosa frase «todos los moradores de la tierra» (Dn 4:32). La variación Ketiv-Qere entre darin y dayrin refleja diferencias dialectales del arameo en la ortografía, sin distinción semántica. La evidencia de las traducciones es notablemente uniforme: español «habitan/habitantes», francés «habiter», alemán «wohnen», todas apuntando a un único concepto residencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1755', 'spa', 'Generación o era: los contemporáneos de un período, la posteridad sucesiva, o la fórmula ''de generación en generación'' como expresión de perpetuidad.', 'Una de las palabras rítmicamente más poderosas del hebreo, דּוֹר conjuga la concreción de una cohorte viviente con la abstracción del tiempo ilimitado. Cuando Moisés condena a ''esta generación torcida y perversa'' (Dt 32:5), דּוֹר designa a las personas que están de pie ante él. Pero en la fórmula cultual לְדֹרֹתֵיכֶם (''por vuestras generaciones'', Gn 17:9; Éx 12:14), se proyecta hacia la perpetuidad: cada cohorte futura hereda la obligación del pacto. La fórmula distributiva מִדּוֹר לְדוֹר (''de generación en generación'', Sal 33:11) comprime todo esto en poesía. El cognado árabe دَوْر (''ciclo, revolución'') apunta a la concepción circular del tiempo que subyace al vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1756', 'spa', 'Dor; ciudad costera cananea en el territorio de Manasés, al sur del monte Carmelo sobre el Mediterráneo.', 'Nombre de una antigua ciudad portuaria cananea situada en la costa mediterránea al sur del monte Carmelo, dentro de la asignación tribal de Manasés. Conocida en fuentes cuneiformes como Du''ru, Dor aparece en listas de conquista (Jos 11:2; 12:23) y en el registro de la incapacidad de Manasés para expulsar a sus habitantes (Jue 1:27). La expresión «Nafat-Dor» (alturas/costa de Dor) designa su distrito más amplio. Bajo Salomón sirvió como uno de los doce distritos administrativos (1 Re 4:11). El sitio moderno se identifica con Tantura en la costa israelí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1758', 'spa', 'Trillar grano; por extensión, pisotear o aplastar a pueblos o naciones en juicio.', 'Verbo agrícola en su esencia, que describe el acto físico de trillar —separar el grano de la paja pisoteando o golpeando. Los cognados aparecen en todas las lenguas semíticas (árabe dāsa, acadio dāšu, arameo dūsh), todos enraizados en el mismo movimiento de pisoteo. Los profetas toman esta vívida imagen campesina y la emplean como metáfora: las naciones son trilladas bajo el juicio de Dios (Is 25:10; Hab 3:12), y la propia Sión es llamada a «trillar» a sus opresores (Mi 4:13). Los sentidos literal y figurado están estrechamente ligados, ya que la trilla antigua implicaba literalmente pisotear.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1760a', 'spa', 'Empujar, arrojar, expulsar por la fuerza; (part. Nifal) desterrado, expulsado; (pasivo) ser derribado, ser abatido.', 'Empujar, arrojar, expulsar por la fuerza; (part. Nifal) desterrado, expulsado; (pasivo) ser derribado, ser abatido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1763', 'spa', 'Temer, estar aterrorizado; en voz pasiva, terrorífico o espantoso (verbo arameo usado en Daniel).', 'Verbo arameo que aparece exclusivamente en Daniel y abarca todo el espectro del pavor en la corte de Nabucodonosor. Su participio pasivo describe a la cuarta bestia terrorífica (Dan 7:7, 19) y la imponente estatua de Daniel 2:31, mientras que su participio activo expresa el temblor de las naciones ante un rey o ante Dios (Dan 5:19; 6:26). En la conjugación Pael, un sueño «atemoriza» al propio rey (Dan 4:5). Así, el verbo opera en dos direcciones: el terror infligido y el terror experimentado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1765', 'spa', 'Impulsar, apresurar, apremiar; verbo hebreo tardío que expresa ser presionado o empujado con urgencia.', 'Verbo hebreo tardío que transmite una prisa urgente e impuesta, el tipo de apremio que no admite demora. En Ester 3:15 y 8:14 los correos reales son «impulsados» a entregar los decretos del rey con la mayor celeridad, donde el participio pasivo sugiere que fueron movidos por la autoridad real y no por iniciativa propia. En Ester 6:12, Hamán se apresura a su casa avergonzado tras honrar a Mardoqueo, y en 2 Crónicas 26:20 el rey Uzías es sacado a empujones del templo tras su transgresión leprosa. El verbo implica consistentemente una presión externa o vergüenza que impulsa el movimiento, no una decisión voluntaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1767', 'spa', 'El sustantivo hebreo דַּי comienza sencillamente — ''suficiencia, bastante'' — pero sus combinaciones preposicionales despliegan un abanico sorprendente', 'El sustantivo hebreo דַּי comienza sencillamente — ''suficiencia, bastante'' — pero sus combinaciones preposicionales despliegan un abanico sorprendente de significados. Con la preposición מִן se convierte en מִדֵּי, modismo temporal que significa ''cada vez que, siempre que'', como en las peregrinaciones anuales de Ana (1 S 1:7). Con כְּ se convierte en כְּדֵי, ''conforme a, en proporción a'' (Dt 25:2) o incluso ''como'' (Jue 6:5). Malaquías 3:10 capta el sentido puro magníficamente: Dios derramará bendición ''hasta que no haya suficiente'' — es decir, hasta que su abundancia inagotable desborde toda medida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1768', 'spa', 'Partícula relativa/conjuntiva aramea: que, quien, el cual; de (genitivo); porque; cuando; donde.', 'La partícula aramea דִּי es el elemento funcional por excelencia de la sintaxis del arameo bíblico: pronombre relativo, conjunción, marcador genitivo y más, todo condensado en dos consonantes. Cognada del hebreo אֲשֶׁר y del etiópico ዘ (za), desciende de una raíz demostrativa (''aquel'') que se gramaticalizó como subordinador general. En Daniel y Esdras, דִּי articula prácticamente toda oración compleja, y su versatilidad desafía al traductor: la misma partícula traducida como ''que'' en una cláusula se convierte en ''de'' en la siguiente y en ''porque'' en la tercera. El español que capta los usos relativos, pero requiere palabras diferentes (de, porque, cuando) para funciones genitivas, causales y temporales que דִּי maneja sola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1769', 'spa', 'Dibon — ciudad moabita sobre la Vía Real, asignada a Gad y Rubén, objeto de oráculos proféticos', 'Dibon — ciudad moabita sobre la Vía Real, asignada a Gad y Rubén, objeto de oráculos proféticos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1777', 'spa', 'Juzgar, emitir un veredicto legal; contender o luchar; defender la causa de alguien; por extensión, gobernar o regir.', 'Juzgar, emitir un veredicto legal; contender o luchar; defender la causa de alguien; por extensión, gobernar o regir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1779', 'spa', 'Causa legal, pleito o demanda ante un juez; veredicto judicial, sentencia o acto de juicio.', 'Causa legal, pleito o demanda ante un juez; veredicto judicial, sentencia o acto de juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1780', 'spa', 'juicio, justicia; tribunal o corte que dicta sentencias', 'Sustantivo arameo que aparece exclusivamente en Daniel y Esdras, y designa el juicio judicial o el tribunal que lo emite. En Daniel 4:37 describe la justicia de los caminos de Dios, mientras que en Daniel 7:10 y 7:26 designa el tribunal celestial que se sienta para juzgar. Esdras 7:26 prescribe que se ejecute juicio sobre los transgresores de la ley. El vocablo tiende un puente entre el concepto abstracto de justicia y la institución concreta que la administra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1783', 'spa', 'Dina: hija de Jacob y Lea, figura central en el relato de Siquem en Génesis 34.', 'Dina es la hija de Jacob y Lea, la única hija mencionada por nombre entre los hijos de Jacob. Su nacimiento se registra brevemente en Génesis 30:21, pero su historia ocupa todo Génesis 34, donde sale a visitar a las mujeres de la tierra y es violada por Siquem hijo de Hamor. Sus hermanos Simeón y Leví ejercen una violenta venganza, acto que Jacob recuerda en su lecho de muerte (Gn 49:5-7). Aparece en la lista de quienes descendieron a Egipto con Jacob (Gn 46:15). El nombre probablemente deriva de la raíz d-y-n, ''juzgar''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1785', 'spa', 'Muro de asedio, rampa de asedio; obra militar de tierra construida contra una ciudad fortificada durante un sitio.', 'Sustantivo masculino que designa un muro o rampa de asedio, una estructura militar levantada por las fuerzas sitiadoras contra las murallas de una ciudad fortificada. Las seis ocurrencias bíblicas describen el mismo tipo de construcción ofensiva, asociada consistentemente con «levantar un terraplén» (שָׁפַךְ סֹלְלָה). El término aparece en los relatos del asedio de Jerusalén por Nabucodonosor (2 R 25:1; Jer 52:4) y en las representaciones proféticas y oráculos de guerra de sitio de Ezequiel (Ez 4:2; 17:17; 21:22; 26:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1787', 'spa', 'Disón o Disán — dos jefes de clan horeo descendientes de Seir en las genealogías de Edom (Gn 36; 1 Cr 1).', 'Nombre propio que pertenece a dos individuos distintos en las genealogías edomitas de Génesis 36 y 1 Crónicas 1. El primer Disón es hijo de Seir el horeo, enumerado entre los jefes del territorio antes de que los descendientes de Esaú los desplazaran. El segundo es nieto de Seir a través de Aná, y aparece con leve variación ortográfica como Disán en 1 Crónicas 1:42. El nombre probablemente deriva de una raíz que significa «trilla» o designa una especie de gacela, acorde con el mundo pastoral del territorio de Seir en las tierras altas de Transjordania.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1789', 'spa', 'Disán, jefe de clan horeo descendiente de Seír', 'Nombre propio de un hijo de Seír el horeo, incluido entre los jefes de clan de Edom. Disán aparece en los registros genealógicos de Génesis 36 y 1 Crónicas 1, donde sus descendientes se enumeran junto a otras familias horeas. El nombre se confunde a veces en el texto con el estrechamente emparentado Disón (H1787), lo que genera lecturas variantes en las distintas versiones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1790', 'spa', 'Aplastado, oprimido; usado poéticamente para referirse a los desvalidos y afligidos que buscan justicia de Dios.', 'Adjetivo poético que describe a alguien que ha sido aplastado o abatido, ya sea física o socialmente. Los Salmos lo emparejan con «huérfano» y «pobre» para retratar a los vulnerables que Dios defiende (Sal 9:9; 10:18; 74:21). En Proverbios 26:28 se desplaza ligeramente para designar a las víctimas de una lengua mentirosa. En todo su campo semántico, el término destaca una victimización sistemática más que un revés pasajero, señalando a quienes necesitan la vindicación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1791', 'spa', 'Pronombre demostrativo arameo ''este/esta'' (m. dek, f. dak); usado pospositivamente en Esdras y Daniel', 'Un pronombre demostrativo arameo que significa ''este/esta'', siempre colocado después del sustantivo al que modifica. La forma masculina dek y la femenina dak aparecen a lo largo de la correspondencia oficial de Esdras, donde el pronombre típicamente modifica sustantivos clave en contextos administrativos: ''esta ciudad'' (qiryeta dak, Esd 4:13-21), ''esta casa de Dios'' (bet elaha dek, Esd 5:17; 6:7-8, 12). Su contraparte plural es illek. La posición pospositiva lo distingue del demostrativo arameo más común dena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1792', 'spa', 'Aplastar o quebrantar; figuradamente, oprimir o quebrar el espíritu; como participio, los contritos o quebrantados de corazón. Un verbo poético que ab', 'Aplastar o quebrantar; figuradamente, oprimir o quebrar el espíritu; como participio, los contritos o quebrantados de corazón. Un verbo poético que abarca desde la destrucción física hasta la quebradura espiritual. En la conjugación Piel, Dios aplasta a Rahab-Egipto como un cadáver (Sal 89:10) y los opresores pisotean al afligido (Sal 94:5). El Siervo Sufriente de Isaías es ''molido'' por la voluntad del Señor (Isa 53:10). Sin embargo, la misma raíz produce una de las imágenes más tiernas de la Escritura: Dios mora con los ''contritos'' (Isa 57:15), los דַּכָּאִים cuyo quebrantamiento se convierte en la puerta misma a la presencia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1794', 'spa', 'Aplastar, ser aplastado (física u opresivamente); del corazón: contrito, quebrantado de espíritu ante Dios.', 'Verbo que aparece solo en los Salmos y que abarca tanto la violencia del aplastamiento físico como la belleza espiritual de la contrición. Los malvados aplastan al indefenso (Sal 10:10), Dios quebranta a su pueblo como prueba (Sal 44:19) y el salmista es aplastado por el sufrimiento (Sal 38:8; 51:8). Sin embargo, en el Salmo 51:17 la misma raíz produce una de las frases más preciadas de la Escritura: al corazón contrito y humillado, Dios no lo despreciará. El español capta este giro con elegancia, desde «aplastado» hasta «contrito», revelando cómo la destrucción física se transforma en receptividad espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1797', 'spa', 'ese, este — pronombre demostrativo arameo que aparece en Daniel', 'Este pronombre demostrativo arameo significa «este» o «aquel» y aparece únicamente en Daniel. Se forma a partir de דֵּךְ más el sufijo demostrativo -ן. Daniel 2:31 lo emplea en el sueño de Nabucodonosor: «esta imagen» (צַלְמָא דִכֵּן). Daniel 7:20-21 lo usa dos veces para «aquel cuerno» (קַרְנָא דִכֵּן) en la visión de la cuarta bestia. El pronombre señala un objeto específico y notable dentro de la visión: la imponente estatua o el cuerno distintivo. Esdras utiliza la forma más simple דֵּךְ, mientras que Daniel emplea consistentemente la forma más larga דִכֵּן.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1798', 'spa', 'carneros (arameo) — machos de ovejas ofrecidos en sacrificio en Esdras', 'Este sustantivo arameo equivale al hebreo זָכָר («macho») y designa carneros empleados en los sacrificios del templo. Las tres apariciones se encuentran en el relato de Esdras sobre la restauración del culto tras el exilio. Esdras 6:9, 6:17 y 7:17 enumeran carneros entre los animales provistos para holocaustos y ofrendas. La palabra es cognada con el siríaco y comparte la doble acepción aramea: tanto «macho» como específicamente «carnero». Estos carneros representan el sistema sacrificial renovado bajo el patrocinio persa, en cumplimiento del decreto de Ciro para apoyar el culto judío.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1800', 'spa', 'Pobre, necesitado; debil, endeble; humilde, bajo; delgado, demacrado', 'Pobre, necesitado; debil, endeble; humilde, bajo; delgado, demacrado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1801', 'spa', 'Saltar, brincar por encima; brincar con gozo o traspasar un umbral', 'Un verbo que describe un movimiento vigoroso de saltar o brincar, empleado tanto literal como figuradamente. En el Salmo 18:29 y 2 Samuel 22:30, el guerrero salta por encima de una muralla gracias a la fuerza de Dios. Isaías 35:6 contempla al cojo saltando como un ciervo en la restauración mesiánica. Cantar de los Cantares 2:8 retrata al amado brincando sobre los collados. Sofonías 1:9 condena a quienes saltan por encima del umbral en un contexto de ritual pagano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1802', 'spa', 'Sacar (agua); figuradamente, extraer o levantar de lo profundo', 'Un verbo que significa sacar agua de un pozo, usado concretamente de las hijas del sacerdote de Madián que sacaban agua para sus rebaños en Éxodo 2:16 y 2:19. En sentido figurado, Proverbios 20:5 habla de una persona entendida que extrae el consejo profundo oculto en el corazón de otro. El Salmo 30:1 extiende la imagen a Dios sacando al salmista de las profundidades, otorgando a la metáfora de sacar agua una dimensión soteriológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1803b', 'spa', 'Los pobres, la clase desposeída (sustantivo colectivo); también débil, endeble (uso adjetival).', 'Sustantivo femenino usado colectivamente para designar el estrato más pobre de la sociedad, especialmente los que quedaron en la tierra tras las deportaciones babilónicas. En Jeremías y 2 Reyes describe consistentemente al remanente empobrecido que Nabuzaradán perdonó porque no tenían nada que valiera la pena tomar (2 R 24:14; 25:12; Jer 40:7; 52:15-16). Una única ocurrencia en Génesis 41:19 cambia de la pobreza económica a la debilidad física, describiendo las vacas flacas y feas del sueño del faraón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1804', 'spa', 'enturbiar, agitar — revolver el agua con los pies, enlodar pisoteando', 'Este verbo significa agitar, enturbiar o enlodar el agua, particularmente al pisotear con los pies. Las tres apariciones se hallan en Ezequiel 32, en oráculos contra Egipto. El versículo 2 acusa al Faraón: «enturbiaste las aguas con tus pies» (en paralelo con «pisoteaste/ensuciaste»). El versículo 13 (dos veces, aunque algunos enmiendan la segunda) promete que las aguas ya no serán enturbiadas por pie de hombre ni de bestia. La imagen retrata la opresión «pisoteadora» de Egipto sobre otras naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1806', 'spa', 'Delaías; nombre teofórico que significa ''Yahvé ha librado/sacado,'' llevado por cinco hombres distintos.', 'Nombre personal teofórico que significa ''Yahvé ha sacado'' o ''Yahvé ha librado,'' compuesto de la raíz דָּלָה (sacar agua) y el nombre divino. Lo llevan al menos cinco individuos: un jefe de división sacerdotal en tiempos de David (1 Cr 24:18), un príncipe que instó al rey Joacim a no quemar el rollo de Jeremías (Jer 36:12, 25), un descendiente de Zorobabel en la línea real (1 Cr 3:24), el cabeza de una familia que no pudo demostrar su ascendencia israelita tras el exilio (Esd 2:60 = Neh 7:62) y el padre de Semaías en tiempos de Nehemías (Neh 6:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1807', 'spa', 'Dalila; mujer filistea del valle de Sorec que traicionó a Sansón entregándolo a los señores filisteos.', 'Nombre propio de la mujer del valle de Sorec que se convirtió en la amante de Sansón y finalmente lo traicionó ante los señores filisteos. Su nombre podría estar relacionado con la raíz hebrea דלל, que significa «colgar» o «ser débil», o con la palabra árabe para «coqueta», aunque la etimología sigue siendo debatida. Las seis ocurrencias aparecen dentro de una sola unidad narrativa en Jueces 16:4-18, donde Dalila presiona insistentemente a Sansón para que revele el secreto de su fuerza, logrando finalmente su objetivo y entregándolo a sus enemigos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1808', 'spa', 'Ramas o ramos, especialmente en la imaginería profética de árboles que representan naciones (Israel, Asiria).', 'El sustantivo plural daliyyot designa las ramas extendidas o ramos de un árbol, empleado casi exclusivamente en metáforas proféticas. Ezequiel es quien más lo utiliza: la vid que representa a Judá extiende sus ramas (Ez 17:6, 7), el esqueje de cedro trasplantado desarrolla ramos nobles (17:23), el gran cedro de Asiria ostenta ramas magníficas (31:7, 9, 12), y la vid de Israel tuvo en otro tiempo ramas robustas aptas para cetros de gobernantes (19:11). Jeremías lo usa una vez refiriéndose a Israel como un olivo verde cuyas ramas Dios incendia (Jer 11:16). La coherente imaginería botánica a lo largo de todas las apariciones hace de este un término vívido para la vitalidad nacional y su pérdida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1809', 'spa', 'Colgar, pender; de ahí languidecer, ser abatido, disminuir en fuerza o recursos.', 'Desde una raíz que significa ''colgar'' o ''pender'', dalal describe un movimiento descendente tanto en sentido físico como metafórico. Los mineros cuelgan suspendidos en los pozos (Job 28:4) y las piernas del cojo penden inútilmente (Prov 26:7). Con mayor frecuencia retrata el abatimiento humano: Israel debilitado ante Madián (Jue 6:6), el salmista clamando ''fui abatido y él me salvó'' (Sal 116:6). También capta el declive de la fuerza nacional: ríos que se secan (Isa 19:6), la gloria de Jacob que se adelgaza (Isa 17:4) y los ojos de Ezequías que desfallecen en la enfermedad (Isa 38:14). Cognados árabes confirman el alcance semántico: tadalla (''colgar'') y da''ufa (''estar débil'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1811', 'spa', 'gotear, destilar, filtrar — de ojos que lloran o techos que gotean', 'Este verbo describe la acción de gotear o destilar, ya sea de lágrimas o de agua. Job 16:20 lamenta: «mi ojo gotea hacia Dios» (דָּלְפָה עֵינִי אֶל־אֱלוֹהַּ). Salmo 119:28 lo emplea figuradamente: «mi alma se deshace de tristeza» (דָּלְפָה נַפְשִׁי מִתּוּגָה). Eclesiastés 10:18 lo aplica a una casa deteriorada: «gotea la casa» (יִדְלֹף הַבָּיִת) por falta de reparaciones. El verbo capta la imagen de líquido cayendo lentamente: lágrimas que brotan, vida que se agota, agua que se filtra entre grietas. Aparece exclusivamente en la literatura sapiencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1814', 'spa', 'Perseguir ardientemente, cazar con intensidad abrasadora; también arder, encender, inflamarse.', 'Un verbo vívido que fusiona la imagen del fuego con la persecución implacable. En su sentido de ''perseguir'', dalaq describe a Labán persiguiendo ardientemente a Jacob (Gén 31:36), a los israelitas cazando a los filisteos tras la caída de Goliat (1 Sam 17:53) y a perseguidores enemigos ''más veloces que águilas'' acosando a los fugitivos de Jerusalén (Lam 4:19). En su sentido de ''arder'', describe fuego literal que se enciende y consume (Ez 24:10; Abd 1:18) y una combustión metafórica: el vino que ''inflama'' (Isa 5:11) y los ''labios ardientes'' que encubren un corazón malvado (Prov 26:23). Ambos sentidos se entrelazan: perseguir ''ardientemente'' es cazar con ardor abrasador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1817c', 'spa', 'Puerta o portón; el cierre con bisagras de una abertura en un edificio, habitación, muralla de ciudad o estructura sagrada. Se refiere a la puerta o p', 'Puerta o portón; el cierre con bisagras de una abertura en un edificio, habitación, muralla de ciudad o estructura sagrada. Se refiere a la puerta o portón físico que cierra una entrada, ya sea de una casa, ciudad, templo o cámara. En Génesis 19:9-10 los hombres de Sodoma presionan contra la puerta de Lot mientras los ángeles lo jalan hacia adentro y la cierran, ilustrando vívidamente la puerta como umbral entre la seguridad y el peligro. La forma dual (דְּלָתַיִם) refleja la construcción característica de doble hoja de las puertas del antiguo Cercano Oriente. El cognado acadio daltu confirma el mismo sentido básico a través de las lenguas semíticas. En Jeremías 36:23 las ''columnas'' de un rollo probablemente reflejan la palabra usada metafóricamente para los paneles u hojas del documento, y en 2 Reyes 12:9 la puerta de un cofre sirve como su tapa o cubierta de apertura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1818', 'spa', 'Sangre como sustancia física (sacrificial, dietética, corporal); derramamiento de sangre o violencia (metonímico); culpa de sangre (jurídico).', 'דָּם es una palabra que late a través de todo el tejido sacrificial, moral y jurídico de la Biblia hebrea. En su sentido más concreto, es el fluido rojo de la vida: rociado sobre los dinteles en la Pascua (Éx 12:7), derramado al pie del altar (Lv 4:30), y prohibido como alimento porque ''la vida está en la sangre'' (Lv 17:11). En su extensión metonímica, frecuentemente señalada por el plural דָּמִים, la sangre representa la violencia misma: la ''ciudad de sangres'' de Ezequiel (Ez 22:2) y el clamor de la sangre de Abel ''desde la tierra'' (Gn 4:10). Una especialización jurídica adicional aparece en fórmulas como ''su sangre sea sobre su cabeza'' (Jos 2:19), donde דָּמִים denota la culpa o responsabilidad por derramar sangre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1819', 'spa', 'Ser semejante, parecerse; comparar, asemejar; pensar, imaginar, planear; una raíz donde semejanza y pensamiento se entrelazan.', 'Ser semejante, parecerse; comparar, asemejar; pensar, imaginar, planear; una raíz donde semejanza y pensamiento se entrelazan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1820', 'spa', 'Ser destruido, perecer o ser cortado; también cesar o detenerse; Qal transitivo: destruir. דָּמָה II es una palabra de final súbito, a menudo violento', 'Ser destruido, perecer o ser cortado; también cesar o detenerse; Qal transitivo: destruir. דָּמָה II es una palabra de final súbito, a menudo violento, bien distinta de su homónimo que significa ''asemejarse.'' En el Nifal lleva el mayor peso teológico: ciudades son ''destruidas'' de la noche a la mañana (Isa 15:1), pueblos enteros ''perecen'' por falta de conocimiento (Os 4:6), e Isaías exclama ''¡Estoy perdido!'' al contemplar la santidad del Señor (Isa 6:5). El Qal intransitivo ofrece un registro más quieto: los ojos de Jeremías no ''cesarán'' de llorar (Jer 14:17; Lam 3:49). El Qal transitivo revela al agente divino detrás de la destrucción: Dios mismo ''destruye'' a la hija de Sión (Jer 6:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1823', 'spa', 'Semejanza, parecido o forma; la cualidad de ser similar en apariencia, usada para la imagen de Dios, formas visionarias y diseños concretos.', 'Semejanza, parecido o forma; la cualidad de ser similar en apariencia, usada para la imagen de Dios, formas visionarias y diseños concretos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1824', 'spa', 'Cesación, quietud, reposo; silencio o inactividad, especialmente en súplicas para que Dios no permanezca inactivo.', 'Denota un estado de quietud, silencio o cesación. Aparece de manera memorable en oraciones urgentes que piden a Dios que no guarde silencio: «no calles» (Sal 83:1). En Isaías 62:6-7, los centinelas reciben la orden de no dar reposo a Dios hasta que Jerusalén sea establecida. La conmovedora frase de Ezequías «en la quietud de mis días» (Is 38:10) evoca la plenitud serena de la vida. Según el contexto, esta quietud puede ser apacible o inquietante, ya que el silencio divino resulta angustiante para quien clama por auxilio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1826a', 'spa', 'Estar en silencio, quedarse quieto, cesar; desde el silencio reverente ante Dios hasta la destrucción forzada; también detenerse y calmar.', 'Estar en silencio, quedarse quieto, cesar; desde el silencio reverente ante Dios hasta la destrucción forzada; también detenerse y calmar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1827', 'spa', 'susurro, silencio — voz queda o el sonido de una calma profunda', 'Este sustantivo femenino denota un susurro o un silencio profundo. Su aparición más célebre es 1 Reyes 19:12: tras el viento, el terremoto y el fuego, Dios habla a Elías en «una voz de suave susurro» (קוֹל דְּמָמָה דַקָּה), frecuentemente traducido como «un silbo apacible y delicado». Job 4:16 describe la visión de Elifaz: «un susurro y una voz oí», un murmullo sobrenatural en la noche. Salmo 107:29 celebra cómo Dios convierte la tormenta «en calma» (לִדְמָמָה). La palabra sugiere tanto un habla queda como la quietud profunda que sigue al tumulto, ambas comunicando la presencia divina con más fuerza que el estruendo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1828', 'spa', 'estiércol, abono; usado figuradamente para cadáveres o muertos dejados insepultos sobre el suelo como desecho', 'Sustantivo masculino que significa ''estiércol'' o ''abono'', empleado exclusivamente en textos proféticos y poéticos como una imagen potente de degradación y desolación. En todas sus apariciones, la palabra describe cadáveres humanos abandonados en el suelo como basura, una imagen vívida del juicio divino que deja a los muertos sin sepultura. Jeremías emplea esta imagen repetidamente: los huesos de los líderes de Jerusalén esparcidos ''como estiércol'' sobre la tierra (Jer 8:2), los caídos yaciendo ''como estiércol sobre la faz del campo'' (Jer 9:22; 16:4; 25:33). El salmista presenta de manera similar a los enemigos derrotados de Israel convertidos en ''estiércol para la tierra'' (Sal 83:10), y se profetiza que el cadáver de Jezabel será ''como estiércol'' en Jezreel (2 Re 9:37).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1832', 'spa', 'Lágrimas; gotas derramadas de los ojos al llorar, en duelo, lamentación o súplica ferviente ante Dios.', 'Lágrimas; gotas derramadas de los ojos al llorar, en duelo, lamentación o súplica ferviente ante Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1834', 'spa', 'Damasco — la antigua capital aramea, ciudad importante del Cercano Oriente y rival perenne de Israel', 'Damasco — la antigua capital aramea, ciudad importante del Cercano Oriente y rival perenne de Israel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1835', 'spa', 'Dan — quinto hijo de Jacob a través de Bilha, la tribu descendiente de él y una ciudad en la frontera norte de Israel. Dan (que significa ''juez'') func', 'Dan — quinto hijo de Jacob a través de Bilha, la tribu descendiente de él y una ciudad en la frontera norte de Israel. Dan (que significa ''juez'') funciona como nombre propio en tres niveles referenciales: la persona, la tribu y el lugar. Como nombre personal designa al hijo nacido de Jacob a través de Bilha, la sierva de Raquel, quien lo llamó Dan porque ''Dios me ha juzgado'' (Gn 30:6). Como nombre tribal identifica a los danitas y su territorio asignado (Jos 19:40-48; Jue 18). Como topónimo marca la ciudad en el extremo norte de Israel, dando lugar al merismo ''desde Dan hasta Beerseba'' (Jue 20:1; 1 S 3:20) — la expresión idiomática estándar para toda la tierra. A lo largo de sus 70 apariciones, todas las lenguas meta conservan el nombre sin cambios: Dan en español, francés, alemán e inglés por igual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1836', 'spa', 'Este, ese, así — pronombre demostrativo arameo usado atributiva y predicativamente en Daniel y Esdras. El demostrativo arameo דְּנָה (denah, ''este'') f', 'Este, ese, así — pronombre demostrativo arameo usado atributiva y predicativamente en Daniel y Esdras. El demostrativo arameo דְּנָה (denah, ''este'') funciona como el principal pronombre demostrativo de cercanía en las porciones arameas bíblicas de Esdras y Daniel. Cognado del hebreo זֶה y relacionado con el siríaco hānā y el nabateo dnḥ, modifica sustantivos atributivamente (''este secreto'', Dn 2:18; ''esta casa'', Esd 5:3) o funciona predicativamente. Con la preposición כְּ produce ''como esto, así'' (Dn 2:10). Aunque modesto en su rango semántico — simplemente señalando un referente — aparece en momentos estructuralmente decisivos: decretos reales, revelaciones proféticas y correspondencia administrativa que configuró la restauración postexílica de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1839', 'spa', 'El danita, adjetivo gentilicio que designa a los miembros de la tribu de Dan', 'Un adjetivo gentilicio que siempre se usa con el artículo definido para identificar a personas o grupos pertenecientes a la tribu de Dan. Aparece en Jueces 13:2 describiendo el clan de Manoa, en Jueces 18 durante la narración de la migración danita, y en 1 Crónicas 12:36 enumerando a los guerreros danitas que se unieron a David. El término funciona como un identificador étnico colectivo más que como un nombre propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1840', 'spa', 'Daniel — ''Dios es mi juez''; el profeta-sabio del exilio y varios otros personajes bíblicos con este nombre', 'Daniel — ''Dios es mi juez''; el profeta-sabio del exilio y varios otros personajes bíblicos con este nombre');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1841', 'spa', 'Daniel (''Dios es mi juez''), nombre propio del profeta exílico y visionario, además de otras dos figuras bíblicas. Nombre teofórico que significa ''Dios', 'Daniel (''Dios es mi juez''), nombre propio del profeta exílico y visionario, además de otras dos figuras bíblicas. Nombre teofórico que significa ''Dios es mi juez'', compuesto de דִּין (''juzgar'') y אֵל (''Dios''). El nombre pertenece principalmente al protagonista del libro de Daniel, un exiliado judío que alcanzó prominencia en las cortes babilónica y persa gracias a su don de interpretación de sueños y su inquebrantable fidelidad (Dn 2-6). Sus visiones apocalípticas (Dn 7-12) se convirtieron en fundamento de la escatología judía y cristiana posterior. El nombre designa también a un hijo de David con Abigail (1 Cr 3:1) y a un sacerdote postexílico que selló el pacto bajo Nehemías (Neh 10:7). Las traducciones interlingüísticas son uniformemente transliteradas (español Daniel, francés Daniel, alemán Daniel), reflejando su familiaridad global como nombre propio bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1843', 'spa', 'Conocimiento, opinión, entendimiento; usado exclusivamente en los discursos de Elihú en Job', 'Un sustantivo que significa conocimiento u opinión, que aparece únicamente en los discursos de Elihú en Job 32-37. Elihú lo emplea tanto para referirse a su propio juicio meditado que desea declarar (Job 32:6, 10, 17) como al conocimiento perfecto que pertenece a Dios (Job 37:16). La palabra transmite un tono de comprensión deliberada y formulada, más que mera conciencia, en consonancia con el estilo retórico autoconsciente de Elihú.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1844', 'spa', 'Conocimiento, entendimiento; conciencia de Dios o de la verdad, referido tanto a la percepción humana como a la omnisciencia divina', 'Sustantivo femenino abstracto derivado del verbo yadá'' (conocer), que denota conocimiento o entendimiento profundo. En el cántico de Ana (1 Sam 2:3), Dios es llamado ''el de''ot'' — un Dios de conocimiento — usando el plural mayestático para expresar la plenitud de la sabiduría divina. El salmista en Sal 73:11 se debate sobre si el Altísimo posee conocimiento de los asuntos humanos. En Isaías y Jeremías la palabra describe el conocimiento profético que los gobernantes y maestros ideales transmitirán. Eliú reclama ''conocimiento perfecto'' en Job 36:4, sugiriendo la audacia de las pretensiones de sabiduría humana. El término apunta a un saber experiencial y profundo, no a mera información.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1845', 'spa', 'Deuel; líder gadita, padre de Eliasaf, registrado en el censo y las ofrendas del desierto.', 'Nombre propio del padre de Eliasaf, quien sirvió como líder de la tribu de Gad durante el período del desierto. El nombre aparece exclusivamente en la fuente sacerdotal de Números (1:14; 7:42, 47; 10:20). La Septuaginta lee Ραγουηλ (Raguel) en todos los casos, y Números 2:14 presenta la variante Reuel (רְעוּאֵל), lo que sugiere que las letras dálet y resh se confundían fácilmente en la tradición escribal. El nombre probablemente significa «conocido de Dios». Todas las traducciones modernas principales lo transliteran simplemente como Deuel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1846', 'spa', 'Apagarse, extinguirse; de llamas, lámparas, y figuradamente de la prosperidad o vida de los impíos.', 'Un verbo poético que aparece casi exclusivamente en la literatura sapiencial y profética, describiendo cómo una llama o lámpara se extingue. En su uso figurado, que predomina en la evidencia bíblica, el apagarse de la lámpara del impío funciona como imagen poderosa del colapso de su prosperidad (Job 18:5-6; Prov 13:9; 20:20; 24:20). Isaías 43:17 extiende la metáfora a ejércitos hostiles apagados como una mecha. El cognado arameo d''ik y el siríaco d''ek confirman el significado nuclear, mientras que las glosas multilingües lo traducen consistentemente con verbos de extinción reflexivos o pasivos (se apaga, s''éteindre).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1847', 'spa', 'Conocimiento, discernimiento; la capacidad de percibir, comprender o reconocer — ocasionalmente como infinitivo verbal ''conocer''. Derivado de la raíz ', 'Conocimiento, discernimiento; la capacidad de percibir, comprender o reconocer — ocasionalmente como infinitivo verbal ''conocer''. Derivado de la raíz יָדַע (''conocer''), este sustantivo denota conocimiento en su sentido más amplio — desde la conciencia práctica hasta el discernimiento espiritual profundo. Aparece en la frase fundacional ''el árbol del conocimiento del bien y del mal'' (Gn 2:9, 17) y figura prominentemente en la literatura sapiencial, donde Proverbios personifica el conocimiento junto a la sabiduría como un don divino (Pr 2:10). La expresión בִּבְלִי דַעַת (''sin conocimiento'') en Deuteronomio 4:42 sirve como término jurídico para la acción involuntaria, mostrando cómo la palabra tiende un puente entre la cognición moral y las categorías jurídicas. Todas las principales lenguas meta lo traducen con un único sustantivo cognitivo: español ''conocimiento'', francés ''connaissance'', alemán ''Erkenntnis''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1849', 'spa', 'Golpear, llamar a la puerta, arrear con fuerza (animales o personas)', 'Este verbo describe un golpear enérgico y repetido. Aparece cuando Jacob teme que sus rebaños sean arreados con excesivo rigor (Gn 33:13), cuando hombres perversos golpean la puerta exigiendo satisfacción violenta (Jue 19:22), y en el clamor de la amada: «¡Escucha! Mi amado está llamando» (Cnt 5:2). El campo semántico abarca tanto el impulso violento —empujar, arrear— como la acción percusiva de llamar a una puerta. Las glosas multilingües confirman esta doble vertiente de impacto físico contundente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1851', 'spa', 'Delgado, fino, pequeño; de ganado flaco, maná en polvo, persona enana o un susurro suave', 'Un adjetivo que abarca un rango sorprendente, desde las vacas demacradas del faraón hasta la voz apacible y delicada en Horeb. En Génesis 41, el ganado y las espigas ''delgadas'' (daq) señalan hambruna. Aplicado a sustancias como el maná y el incienso, pasa a significar ''de grano fino'' o ''en polvo'' (Éx 16:14; Lv 16:12), donde el árabe daqiq (''harina fina'') comparte la misma raíz semítica. De manera más memorable, en 1 Reyes 19:12 describe la cualidad ''delgada'' o suave de la voz de Dios a Elías, un susurro tan tenue que redefine el poder divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1854', 'spa', 'Triturar, pulverizar o moler hasta obtener partículas finas; también ser fino o delgado como resultado de la molienda', 'Un verbo de reducción física, empleado para triturar, machacar y moler sustancias hasta convertirlas en polvo. Aparece en relatos de destrucción de objetos idolátricos, como cuando Josías trituró el poste de Asera junto al arroyo Cedrón (2 R 23:6) y cuando Moisés molió el becerro de oro hasta hacerlo polvo (Éx 32:20). El Hifil causativo lleva la fuerza de pulverizar activamente, mientras que el Qal estativo describe la finura resultante. Isaías emplea tanto las formas activas como las pasivas en imágenes agrícolas, señalando que el grano para pan finalmente se tritura pero no se trilla sin cesar (Is 28:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1855', 'spa', 'Desmenuzar, quebrantar, pulverizar; verbo arameo usado en Daniel para reducir reinos a polvo y ser hecho pedazos', 'Desmenuzar, quebrantar, pulverizar; verbo arameo usado en Daniel para reducir reinos a polvo y ser hecho pedazos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1856', 'spa', 'Traspasar o atravesar mortalmente con un arma; en formas pasivas, ser traspasado, muerto o herido de muerte', 'Traspasar o atravesar mortalmente con un arma; en formas pasivas, ser traspasado, muerto o herido de muerte');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1857', 'spa', 'Deker, nombre propio; uno de los oficiales de distrito de Salomón, posiblemente significa ''penetrante'' o ''arma''', 'Este funcionario sirvió como uno de los doce gobernadores de distrito de Salomón, responsables de abastecer la casa real. La expresión «hijo de Deker» sigue un patrón en la lista administrativa salomónica donde los oficiales se identifican a veces por el nombre paterno. El posible significado del nombre se relaciona con lo punzante o las armas afiladas, aunque tales conexiones etimológicas son especulativas. La lista burocrática demuestra la sofisticación administrativa de Salomón, dividiendo el reino en distritos de abastecimiento con obligaciones mensuales rotativas. Ben-Deker gobernaba una región que incluía varias ciudades en las colinas occidentales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1859', 'spa', 'Generación (arameo); usado en la fórmula ''generación y generación'' para expresar el dominio eterno de Dios.', 'Equivalente arameo del hebreo דּוֹר (''generación''), que aparece exclusivamente en las doxologías de Daniel. Se emplea siempre en la fórmula fija עִם־דָּר וְדָר (''con generación y generación''), proclamando que el reino de Dios perdura de una generación a la siguiente (Dan 4:3, 34). Nabucodonosor confiesa mediante esta expresión que el dominio divino es perpetuo. La duplicación intensifica el significado hacia ''todas las generaciones sucesivas'' o ''por los siglos de los siglos''. El español ''generación'' lo traduce de forma directa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1864', 'spa', 'Sur, dirección meridional: término poético y del hebreo tardío para el sur como punto cardinal. Sustantivo algo literario y del hebreo tardío para ''su', 'Sur, dirección meridional: término poético y del hebreo tardío para el sur como punto cardinal. Sustantivo algo literario y del hebreo tardío para ''sur,'' usado principalmente en las visiones del templo de Ezequiel y en Eclesiastés. A diferencia del más común נֶגֶב (que también designa la región árida del sur) o תֵּימָן (asociado con el extremo sur y Edom), דָּרוֹם funciona como un término direccional neutro, típicamente contrastado con צָפוֹן (''norte'') y a veces con קָדִים (''este'') o יָם (''oeste/mar''). En las elaboradas descripciones del templo de Ezequiel, identifica la puerta sur, las cámaras meridionales y las medidas del lado sur (Ez 40-42). Deuteronomio 33:23 lo empareja con יָם en la bendición de Neftalí, y Job 37:17 invoca el calor sofocante del viento del sur.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1865', 'spa', 'Libertad, liberación de la servidumbre (especialmente en el año del Jubileo); también fluido, dicho de la mirra líquida pura.', 'Un sustantivo enraizado en el concepto de flujo libre y sin impedimento, aplicado tanto a la liberación de personas de la servidumbre como a la cualidad fluida de la mirra líquida. Su uso principal es teológico y jurídico: ''proclamaréis libertad en toda la tierra'' (Lev 25:10, inscrito en la Campana de la Libertad estadounidense) anuncia la liberación jubilar de esclavos y la restitución de propiedades. Isaías 61:1 lo extiende a la liberación mesiánica, y Jeremías 34:8-17 narra un intento fallido de cumplir esta obligación. La única ocurrencia con mirra (Éx 30:23) preserva la raíz física: mor-deror es ''mirra de flujo libre'', la calidad más selecta que gotea naturalmente sin prensado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1867', 'spa', 'Darío — nombre real persa portado por Darío Histaspes, Darío Codomano y ''Darío el Medo''', 'Darío — nombre real persa portado por Darío Histaspes, Darío Codomano y ''Darío el Medo''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1868', 'spa', 'Darío — nombre real persa que llevan Darío Histaspes y ''Darío el Medo'' en las Escrituras', 'La forma hebrea דָּרְיָוֶשׁ reproduce el nombre persa antiguo Dārayavauš (''el que sostiene firmemente el bien''). En Esdras identifica a Darío I Histaspes, bajo cuyo decreto se completó el templo de Jerusalén (Esd 4:24; 5:5-7; 6:1, 12-15). En Daniel nombra al enigmático ''Darío el Medo'' que recibe el reino tras la caída de Belsasar (Dn 5:31; 6:1-28). Hageo y Zacarías fechan sus profecías en ''el segundo año de Darío'' (Hag 1:1; Zac 1:1). Las traducciones europeas emplean consistentemente ''Darius/Darío''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1869', 'spa', 'Pisar, marchar, pisotear; tensar el arco; en Hifil, guiar o conducir por un camino, o hacer pisotear.', 'Pisar, marchar, pisotear; tensar el arco; en Hifil, guiar o conducir por un camino, o hacer pisotear.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1870', 'spa', 'Camino, senda, vía; metafóricamente modo de vida, conducta o costumbre; también viaje o trayecto', 'דֶּרֶךְ es uno de los sustantivos más versátiles de la Biblia hebrea, sirviendo como término geográfico concreto y como una de las metáforas más ricas de la Escritura. Puede designar un camino polvoriento entre ciudades o la ruta de una caravana, pero cobra verdadera fuerza al describir la trayectoria moral de una vida. La declaración del Salterio de que Dios «conoce el camino de los justos» (Sal 1:6) y la advertencia proverbial contra «el camino de los impíos» dependen de este deslizamiento fluido entre senda física y conducta ética. Todas las lenguas conservan esta dualidad: español camino, alemán Weg, francés chemin y árabe طريق funcionan a la vez como «ruta» y «modo de vida».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1871', 'spa', 'Dárico o dracma; moneda de oro usada en las donaciones para la reconstrucción del templo en época posexílica.', 'Moneda de oro de la era persa mencionada exclusivamente en contextos posexílicos de recaudación para el templo. El término aparece en Esdras 2:69 y Nehemías 7:70–72 en los registros de generosas donaciones para la reconstrucción del templo de Jerusalén. Si se refiere exactamente al dárico persa (una moneda de oro con la imagen de un arquero arrodillado) o a la dracma griega sigue siendo objeto de debate, aunque el contexto posexílico favorece la identificación con el dárico. La forma con álef prostético אֲדַרְכּוֹן aparece junto a דַּרְכְּמוֹן, ambas probablemente préstamos del persa o del griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1875', 'spa', 'Buscar, consultar, investigar, requerir; ser consultado (Nifal); cuidar de', 'Verbo de persecución deliberada y decidida, ya sea buscar a Dios en oración, consultar a un profeta para recibir guía o investigar un asunto legal con rigor judicial. Su cognado árabe darasa (''estudiar, pisar repetidamente'') conserva el sentido de empeño persistente. El rango semántico abarca desde la búsqueda general (1 Cr 16:11) hasta la consulta formal de oráculos divinos (Gn 25:22), la investigación forense (Dt 13:14) y la rendición de cuentas en el pacto, donde Dios ''requiere'' la sangre (Gn 9:5). En el Nifal, Dios mismo se convierte en aquel que es buscado o consultado, a menudo con la nota conmovedora de que permitió --o rehusó-- ser hallado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1877', 'spa', 'Hierba, vegetación tierna; también trilla (de una raíz separada דּוּשׁ)', 'El sustantivo דֶּשֶׁא es una de las palabras principales de la Biblia para la vegetación fresca y tierna: el manto verde que brota de la tierra por mandato de Dios en Gn 1:11-12. Denota hierba joven antes de madurar, en contraste con חָצִיר (heno seco) en Pr 27:25. La lluvia la refresca (Dt 32:2), Dios la hace brotar (Job 38:27) y el salmista descansa junto a sus praderas (Sal 23:2). En la profecía y la sabiduría se convierte en metáfora de la fragilidad humana: los malvados brotan como דֶּשֶׁא solo para marchitarse (Sal 92:7; Is 15:6). Una sola aparición (Jer 50:11) representa una raíz verbal distinta que significa ''trillar''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1878', 'spa', 'Estar o volverse gordo; en Piel, engordar, ungir, aceptar con favor o retirar las cenizas del altar', 'Estar o volverse gordo; en Piel, engordar, ungir, aceptar con favor o retirar las cenizas del altar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1879', 'spa', 'Gordo, rico, vigoroso; lleno de savia o aceite', 'Este adjetivo evoca abundancia y vitalidad. Describe el pan como «rico» proveniente de tierra fértil (Is 30:23), a los justos como árboles «llenos de savia» que florecen (Sal 92:14), y a «los prósperos de la tierra» que se postran ante Dios (Sal 22:29). BDB sugiere que puede denotar plenitud de aceite o savia, en consonancia con la imagen de una vida verde y bien alimentada. El término transmite prosperidad y vigor saludable, no simple corpulencia física.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1880', 'spa', 'Cenizas grasientas (de ofrendas sacrificiales); gordura, riqueza, abundancia (de bendición divina o fertilidad)', 'El sustantivo דֶּשֶׁן abarca dos facetas de la grasa en la vida israelita antigua. En el sistema levítico, designa las cenizas grasientas que quedan en el altar después de consumirse los holocaustos: el sacerdote debe retirar el דֶּשֶׁן y llevarlo fuera del campamento (Lv 1:16; 4:12; 6:10-11). Es un término cúltico técnico con un referente distintivamente físico. Pero la misma palabra también evoca riqueza, abundancia y provisión exuberante: el olivo se jacta de su דֶּשֶׁן (Jue 9:9) y la casa de Dios rebosa de él (Sal 36:8). Esta dualidad refleja la cosmovisión hebrea: la grasa es tanto un residuo sagrado del sacrificio como una metáfora de la generosidad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1881', 'spa', 'Ley, regulación o estatuto; decreto o edicto real; sentencia o veredicto judicial.', 'Ley, regulación o estatuto; decreto o edicto real; sentencia o veredicto judicial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1882', 'spa', 'Ley, código legal; decreto o edicto real; sentencia o veredicto judicial (arameo, préstamo del persa)', 'Un sustantivo arameo tomado del persa que aparece exclusivamente en Esdras y Daniel, donde transita la cargada intersección entre la Torá divina y la legislación imperial. En Esdras 7, el propio rey persa reconoce la ''ley de tu Dios'' (dat ''elahak). Sin embargo, en Daniel 2:13 y 2:15 la palabra se estrecha a un decreto real específico, una orden ejecutiva particular. Lo más llamativo es Daniel 2:9, donde Nabucodonosor acusa a los sabios y la palabra adquiere la fuerza de una sentencia o pena judicial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1885', 'spa', 'Datán — un rebelde rubenita que, junto con Abiram, desafió la autoridad de Moisés y fue tragado por la tierra.', 'Datán — un rebelde rubenita que, junto con Abiram, desafió la autoridad de Moisés y fue tragado por la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1886', 'spa', 'Dotán (topónimo en el norte de Israel)', 'Ciudad del norte de Israel, al norte de Samaria, donde los hermanos de José habían trasladado sus rebaños (Gn 37:17) y donde Eliseo fue rodeado por un ejército arameo, hasta que los ojos de su siervo fueron abiertos para ver carros de fuego (2 R 6:13). El sitio ha sido identificado con la actual Tell Dotán. Las tres ocurrencias aparecen en relatos que involucran desplazamiento o movimientos militares, y las glosas multilingües conservan uniformemente el nombre propio con leves variaciones ortográficas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1889', 'spa', 'הֶאָח — ¡Ajá!; interjección exclamativa que expresa gozo malicioso, escarnio o satisfacción triunfante.', 'הֶאָח — ¡Ajá!; interjección exclamativa que expresa gozo malicioso, escarnio o satisfacción triunfante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1891', 'spa', 'Volverse vano, obrar con vacuidad; ser engañado o llenarse de falsas esperanzas', 'Un verbo denominativo de הֶבֶל («vanidad») que describe el proceso de volverse vacío o inútil en un sentido moral y espiritual. En 2 Reyes 17:15 y Jeremías 2:5, Israel siguió la vanidad y con ello se hizo vano, un agudo juego de palabras con el sustantivo. El Salmo 62:10 advierte contra desmoralizarse por la rapiña. Job 27:12 pregunta por qué las personas se muestran absolutamente vanos. El Hifil en Jeremías 23:16 describe a los falsos profetas que hacen que otros abracen la ilusión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1892', 'spa', 'Vapor, aliento, soplo fugaz; figuradamente, vanidad, futilidad, absurdo; aplicado a los ídolos como vaciedades sin valor.', 'Vapor, aliento, soplo fugaz; figuradamente, vanidad, futilidad, absurdo; aplicado a los ídolos como vaciedades sin valor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1893', 'spa', 'Abel (Hevel); segundo hijo de Adán, cuya ofrenda Dios aceptó y quien fue asesinado por su hermano Caín.', 'Hevel (Abel) es el segundo hijo de Adán y Eva, pastor de ovejas cuyo sacrificio de los primogénitos de su rebaño halló favor ante Dios (Gén 4:4). Su hermano Caín, labrador de la tierra, lo mató por celos, cometiendo el primer asesinato de las Escrituras (Gén 4:8). La respuesta de Dios a Caín, ''la voz de la sangre de tu hermano clama a mí desde la tierra'' (Gén 4:10), convierte a Hevel en paradigma del sufrimiento inocente. El nombre puede estar relacionado con el sustantivo común hevel (''aliento, vapor''), aunque BDB sugiere un posible cognado asirio ablu (''hijo'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1896', 'spa', 'Hegai (también Hegué); el eunuco del rey Asuero encargado de la custodia del harén real.', 'Nombre propio del eunuco del rey puesto a cargo del harén en la corte de Asuero (Jerjes). Aparece cuatro veces en Ester 2, supervisando la reunión de las jóvenes doncellas y encargándose después de los preparativos de Ester (Est 2:3, 8, 15). El nombre presenta variantes ortográficas: הֵגֵא (Hegué) y הֵגַי/הֵגָי (Hegai), y es probablemente de origen persa, posiblemente relacionado con el nombre Hegias conocido por Ctesias. Todas las traducciones simplemente transliteran como ''Hegai''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1897', 'spa', 'Meditar, musitar, gemir; verbo onomatopéyico para sonidos vocales graves: murmurar la Torá, gemir, tramar, rugir.', 'Meditar, musitar, gemir; verbo onomatopéyico para sonidos vocales graves: murmurar la Torá, gemir, tramar, rugir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1898', 'spa', 'Quitar, apartar; expulsar o enviar al destierro', 'Este verbo aparece en la literatura sapiencial y profética con el sentido de remover o expulsar. Proverbios lo emplea dos veces para quitar la escoria de la plata y apartar al impío de la presencia del rey (Pr 25:4-5), estableciendo una metáfora de purificación. Isaías 27:8 es debatido: Dios «apartó» (envió al exilio) a su pueblo con un viento recio, o bien lo «aventó». Las glosas multilingües confirman la idea central de remoción enérgica o expulsión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1899', 'spa', 'Murmullo, gemido, suspiro; sonido de angustia o lamento', 'Sustantivo que evoca sonidos graves y ominosos. Describe el «retumbar» del trueno como voz de Dios (Job 37:2), la brevedad de la vida humana «como un suspiro» (Sal 90:9) y el contenido del rollo de Ezequiel: «lamentaciones, gemidos y ayes» (Ez 2:10). La palabra abarca tanto fenómenos naturales (el trueno) como expresiones humanas de dolor o fugacidad. Las glosas multilingües captan el registro afectivo: murmullo, suspiro y gemido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1902', 'spa', 'Música resonante, meditación, reflexión; desde la quieta reflexión del corazón hasta la melodía instrumental.', 'Sustantivo de rico contenido semántico que abarca tanto lo audible como lo interior. Por un lado designa la música resonante ejecutada con la lira (Sal 92:3), y por otro, la meditación silenciosa del corazón ante Dios (Sal 19:14). En Lamentaciones 3:62 adquiere un matiz más sombrío, describiendo las maquinaciones y murmuraciones hostiles de los enemigos. El término aparece incluso como posible indicación musical o litúrgica junto a Selah (Sal 9:16). El español oscila entre ''meditación'' para el sentido reflexivo y ''Higgaion'' cuando funciona como señal de interpretación musical.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1904', 'spa', 'Hagar — sierva egipcia de Sara, madre de Ismael, figura central en las narrativas del pacto abrahámico.', 'Hagar — sierva egipcia de Sara, madre de Ismael, figura central en las narrativas del pacto abrahámico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1905', 'spa', 'Hagrita(s); grupo tribal nómada al este de Galaad, también usado como adjetivo gentilicio y patronímico', 'Los hagritas eran un pueblo seminómada que habitaba al este del Jordán, posiblemente de ascendencia aramea o ismaelita. Las tribus de Rubén, Gad y la media tribu de Manasés guerrearon contra ellos y los vencieron (1 Cr 5:10, 19-20), mientras que el Sal 83:6 los incluye entre la confederación que conspiraba contra Israel. Como adjetivo gentilicio, Jaziz el hagrita supervisaba los rebaños de David (1 Cr 27:31), un rol que probablemente reflejaba la pericia pastoril de su pueblo. En 1 Cr 11:38 aparece como patronímico: Mibhar ben-Hagrí, uno de los valientes de David.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1907', 'spa', 'Consejero, ministro (arameo); alto funcionario real asesor en las cortes babilónica y persa.', 'Préstamo arameo del persa que designa a un alto funcionario de la corte: un consejero o ministro que asesora al rey. Aparece exclusivamente en Daniel, donde estos consejeros presencian los dramáticos encuentros de Nabucodonosor con el poder divino: observan a los tres varones ilesos en el horno de fuego (Dan 3:24, 27) y están presentes cuando se le restituye la razón al rey (Dan 4:36). En Dan 6:7 conspiran para tender una trampa a Daniel. El español ''consejeros'' lo traduce de forma directa y consistente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1908', 'spa', 'Hadad — nombre propio llevado por varios reyes edomitas y un adversario de Salomón.', 'Hadad — nombre propio llevado por varios reyes edomitas y un adversario de Salomón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1909', 'spa', 'Hadadezer — el rey arameo de Soba derrotado por David; el nombre significa ''Hadad es (mi) ayuda''.', 'Hadadezer — el rey arameo de Soba derrotado por David; el nombre significa ''Hadad es (mi) ayuda''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1913a', 'spa', 'Hadoram (nombre propio personal y tribal)', 'Nombre propio con dos referentes bíblicos: una tribu árabe descendiente de Joctán (Gn 10:27; 1 Cr 1:21) y un hijo del rey de Hamat enviado como emisario ante David (1 Cr 18:10). El nombre aparece en contextos genealógicos y diplomáticos. En 2 Samuel 8:10 el texto paralelo lee Joram, pero la evidencia del griego y la crítica textual favorecen Hadoram como la lectura original. Las traducciones lo conservan con mínima variación ortográfica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1916', 'spa', 'Estrado; siempre en constructo con ''pies'', usado figuradamente de la tierra, el arca o el templo como reposapiés de Dios', 'Sustantivo masculino que significa estrado o escabel, que aparece siempre en la frase hadom raglayim (estrado de los pies). Nunca se usa literalmente como mueble, sino que funciona como una poderosa metáfora teológica. En Isa 66:1 el cielo es el trono de Dios y la tierra su estrado; en Lam 2:1 el santuario es llamado el estrado de sus pies, derribado en juicio. El arca del pacto se describe como estrado de Dios en 1 Cr 28:2, y el Sal 110:1 aplica la imagen a la sujeción de los enemigos del rey mesiánico. El término español ''estrado'' conserva la connotación regia de una plataforma bajo los pies de un soberano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1918', 'spa', 'Mirto; el arbusto perenne Myrtus communis, símbolo de restauración y gozo festivo en textos proféticos y postexílicos', 'El mirto (Myrtus communis), un arbusto aromático perenne nativo de la cuenca mediterránea. En la visión nocturna inaugural de Zacarías (Zac 1:8, 10, 11), el ángel del Señor se encuentra entre mirtos en una hondonada — un escenario frondoso y oculto que enmarca el mensaje de consuelo divino. Isaías empareja dos veces el mirto con otros árboles nobles en visiones de transformación escatológica: espinos reemplazados por mirto (Isa 55:13), desierto plantado con mirto junto a cedro y ciprés (Isa 41:19). Neh 8:15 incluye ramas de mirto entre el follaje recolectado para las cabañas de Sucot.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1920', 'spa', 'Empujar, arrojar físicamente; expulsar o echar de un lugar; rechazar o despreciar en sentido figurado.', 'Empujar, arrojar físicamente; expulsar o echar de un lugar; rechazar o despreciar en sentido figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1921', 'spa', 'Honrar, mostrar respeto, adornar; también del terreno escabroso o elevado; en reflexivo, glorificarse a sí mismo.', 'Enraizado en la idea de hinchazón o plenitud, este verbo abarca tanto el honrar a personas como la descripción de un terreno imponente. La Torá ordena ''honrarás (וְהָדַרְתָּ) el rostro del anciano'' (Lv 19:32), mientras que la misma raíz advierte contra el favoritismo en el tribunal (Éx 23:3; Lv 19:15). Isaías emplea el participio pasivo para describir a Dios como ''majestuoso'' con vestiduras carmesíes (Is 63:1) y, llamativamente, un terreno escabroso que será allanado ante Ciro (Is 45:2). El Hitpael en Pr 25:6 advierte contra glorificarse ante el rey, subrayando la autoexaltación reflexiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1922', 'spa', 'Glorificar, honrar (a Dios); verbo arameo en Pael', 'Verbo arameo en la conjugación Pael que aparece exclusivamente en Daniel, siempre con Dios como objeto. Nabucodonosor «glorificó» al Altísimo tras su restauración (Dn 4:34, 37), y Daniel reprende a Belsasar por no haber «glorificado» al Dios que sostiene su aliento (Dn 5:23). Es un lenguaje cúltico y regio que expresa el reconocimiento de la soberanía divina. Las traducciones convergen uniformemente en la idea de dar honra y gloria a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1923', 'spa', 'Honor, majestad, esplendor (especialmente de un rey); arameo', 'Sustantivo arameo que denota el esplendor y la majestad regia, presente en el relato de la locura y restauración de Nabucodonosor en Daniel. La «majestad» le fue devuelta al rey (Dn 4:30, 36), y Dios había otorgado «majestad» a Nabucodonosor (Dn 5:18). La palabra evoca la dignidad visible y la grandeza soberana, no una virtud interior, sino la manifestación externa de la autoridad real y del favor divino que la sustenta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1926', 'spa', 'Ornamento, esplendor, majestad; la belleza radiante, la grandeza imponente o el honor conferido de Dios o de las personas', 'Ornamento, esplendor, majestad; la belleza radiante, la grandeza imponente o el honor conferido de Dios o de las personas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1927', 'spa', 'adorno, esplendor, gloria; especialmente la hermosura de la santidad en el culto litúrgico', 'Sustantivo femenino que significa adorno, esplendor o gloria, y que aparece exclusivamente en frases constructas. Cuatro de sus cinco apariciones forman la expresión הַדְרַת־קֹדֶשׁ, ''el esplendor de la santidad'', fórmula litúrgica vinculada al culto público del Señor en 1 Crónicas 16:29, 2 Crónicas 20:21, Salmo 29:2 y Salmo 96:9. Se trata de una invitación solemne a adorar al Señor revestido de majestad sagrada. Proverbios 14:28 aplica el término a la gloria real, declarando que la multitud de pueblo es el esplendor del rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1928', 'spa', 'Hadadezer, rey arameo de Zobá; poderoso enemigo de David cuyo nombre significa ''Hadad es ayuda''', 'Este formidable gobernante arameo controlaba Zobá, un reino importante al norte de Damasco, hasta que David lo derrotó de manera decisiva. El nombre incorpora al dios de la tormenta Hadad, testimoniando la cultura religiosa aramea. Múltiples relatos de las victorias de David sobre él aparecen en Samuel, Reyes y Crónicas, con variantes textuales entre «Hadadezer» y «Hadarezer». Comandaba fuerzas considerables, incluyendo carros y jinetes, extendiendo su territorio hacia el Éufrates. El triunfo de David sobre un enemigo tan poderoso demostró su creciente dominio en la región. Inscripciones arameas confirman la autenticidad y formación típica del nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1931', 'spa', 'Él, ella, ello (pronombre personal); aquel/aquella (demostrativo); es, esto es (copulativo identificador)', 'El pronombre הוּא (masculino) / הִיא (femenino) es una de las palabras gramaticales más versátiles del hebreo. En su función principal es simplemente «él», «ella» o «ello», retomando un referente previamente mencionado. Pero el hebreo conserva un estrato demostrativo más antiguo en el que הוּא significa «aquel» o «aquel mismo», señalando una entidad específica y a menudo distante, como se aprecia en expresiones como «aquella noche» (Gn 19:35) y «aquel día» (Gn 26:24). Ocasionalmente funciona como cópula, afirmando identidad: «él es» o «esto es», como en Lv 10:3.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1932', 'spa', 'Él, ella, ello (pronombre arameo de tercera persona); aquel/aquella (uso demostrativo)', 'Él, ella, ello (pronombre arameo de tercera persona); aquel/aquella (uso demostrativo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1933b', 'spa', 'llegar a ser, ser, suceder; sinónimo poético poco frecuente de הָיָה', 'Verbo poco frecuente que funciona como sinónimo poético del habitual הָיָה (''ser, llegar a ser''). En Génesis 27:29, Isaac ordena a Jacob: ''sé señor de tus hermanos''. Isaías 16:4 emplea el imperativo femenino en una súplica para que Moab ofrezca refugio, posiblemente imitando el dialecto moabita. Eclesiastés usa el participio (2:22) y el imperfecto (11:3) para reflexionar sobre lo que llega a suceder. Nehemías 6:6 cita un rumor acerca de lo que alguien está ''llegando a ser''. El cognado arameo se convirtió en la forma estándar para ''ser''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1934', 'spa', 'Verbo arameo: ser, existir; llegar a ser o acontecer; también se usa como auxiliar perifrástico con participios.', 'Verbo arameo: ser, existir; llegar a ser o acontecer; también se usa como auxiliar perifrástico con participios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1935', 'spa', 'Esplendor, majestad u honor; la radiancia sobrecogedora de Dios, la realeza o la dignidad y distinción personal', 'Esplendor, majestad u honor; la radiancia sobrecogedora de Dios, la realeza o la dignidad y distinción personal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1938', 'spa', 'Hodavías (nombre propio); posiblemente «cantos de alabanza»', 'Nombre propio que llevan varios individuos en las listas postexílicas (1 Cr 5:24; 9:7; Esd 2:40). Su etimología es debatida: BDB menciona un posible sustantivo abstracto que significa «cantos de alabanza» o un infinitivo con sentido de «alabar», aunque la función predominante es la de nombre personal. Las traducciones conservan el nombre con ligeras variaciones ortográficas. Aparece en contextos genealógicos y censales, identificando a jefes de familias o grupos levíticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1940', 'spa', 'Hodías; nombre propio teofórico que significa ''mi esplendor es Yah,'' portado por varias figuras postexílicas.', 'Nombre teofórico que significa ''mi esplendor es Yah,'' llevado por al menos tres individuos distintos de la comunidad postexílica. Uno es un hombre de Judá mencionado en las genealogías (1 Cr 4:19). Otros dos son levitas que ayudaron al pueblo a comprender la Ley durante la lectura pública de Esdras (Neh 10:10, 13), y un jefe del pueblo que selló el pacto (Neh 10:18). Las principales traducciones transliteran el nombre como ''Hodías'' en español y ''Hodiah'' o ''Hodijah'' en inglés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1942', 'spa', 'Destrucción, calamidad, ruina envolvente; también deseo (maligno), codicia voraz', 'El sustantivo הַוָּה lleva un peso sombrío y ominoso en la poesía y profecía hebreas. En su sentido primario significa ruina devastadora o calamidad, el tipo de destrucción avasalladora que traga a los malvados. Los Salmos son su hábitat natural: la garganta de los malvados es un sepulcro abierto, ''su interior es הַוּוֹת'' (Sal 5:9, citado por Pablo en Ro 3:13). Job dice que su propia הַוָּה pesa más que la arena (Job 6:2). Un segundo sentido, más raro, describe el deseo codicioso o la avidez: ''el deseo de los malvados'' en Proverbios 10:3 y 11:6, vinculando el apetito interior con la ruina exterior. El cognado árabe هَاوِيَة (''abismo, infierno'') ilumina la imagen de un abismo que devora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1943', 'spa', 'Ruina, desastre, calamidad', 'Sustantivo que expresa condenación y destrucción. Isaías advierte que «la calamidad caerá sobre ti» (Is 47:11), y Ezequiel profetiza «desastre sobre desastre» (Ez 7:26), repitiendo la palabra para lograr un efecto retórico aplastante. No se trata de dificultades ordinarias, sino de una ruina en cascada: el juicio divino desplegándose en oleadas sucesivas. Las traducciones en diversas lenguas captan uniformemente esta fuerza catastrófica y abrumadora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1945', 'spa', 'Interjección exclamativa: ''!ay! !ay de!'' en lamento o juicio; raramente ''!ea! !venid!'' como llamado de atención.', 'Interjección exclamativa: ''!ay! !ay de!'' en lamento o juicio; raramente ''!ea! !venid!'' como llamado de atención.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1946', 'spa', 'Ir, caminar (arameo); movimiento físico y conducta figurada, incluyendo andar con soberbia.', 'Cognado arameo del hebreo הָלַךְ, que significa ir o caminar. En Esdras describe el desplazamiento de personas y objetos: los utensilios del templo que regresan a Jerusalén (Esd 6:5) y el permiso para que los voluntarios suban (Esd 7:13). En Daniel adquiere un matiz más vívido: tres hombres caminando en el horno ardiente (Dan 3:25) y Nabucodonosor paseando por la azotea de su palacio (Dan 4:26). La extensión figurada a ''andar con soberbia'' (Dan 4:34) conecta el movimiento físico con la conducta moral, una metáfora común en las lenguas semíticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1947', 'spa', 'Locura, insensatez vista como temeridad irracional; usado exclusivamente en Eclesiastés para denotar demencia moral e intelectual.', 'Sustantivo femenino que aparece solo en plural y exclusivamente en Eclesiastés, donde el Predicador se propone examinar la sabiduría junto a su opuesto. La palabra no describe una simple tontería sino un trastorno profundo del razonamiento moral: la clase de insensatez que el sabio investiga precisamente para rechazarla. El español ''locura'' y el alemán ''Wahnsinn'' conservan la intensidad del término: no se trata de ignorancia sino de un abandono voluntario de la razón. En Ecl 9:3 aparece junto al mal mismo, revelando que el autor entiende la locura como una condición espiritual y ética, no meramente psicológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1949', 'spa', 'murmurar, rugir, alborotarse; causar confusión o arrojar al desconcierto', 'Verbo que expresa agitación tumultuosa: el rugido de una multitud, la turbación interior de la angustia o el acto divino de sembrar el pánico entre los enemigos. En Rut 1:19 toda la ciudad se alborota ante el regreso de Noemí. En 1 Samuel 4:5 la tierra retumba con el grito de guerra de Israel. 1 Reyes 1:45 describe a Jerusalén bullendo de entusiasmo por la unción de Salomón. El Salmo 55:2 vuelve la mirada hacia dentro: el salmista gime con agitación incesante. Miqueas 2:12 lo aplica al murmullo de un rebaño reunido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1952', 'spa', 'Riqueza, bienes valiosos; raramente ''suficiente, bastante'' -- un término poético concentrado en Proverbios y Ezequiel', 'Riqueza, bienes valiosos; raramente ''suficiente, bastante'' -- un término poético concentrado en Proverbios y Ezequiel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1954', 'spa', 'Oseas (''salvación''): nombre original de Josué hijo de Nun; también el último rey de Israel, el profeta Oseas y otros líderes israelitas.', 'Oseas (''salvación''): nombre original de Josué hijo de Nun; también el último rey de Israel, el profeta Oseas y otros líderes israelitas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1955', 'spa', 'Hosaías (''Yah ha salvado''; nombre propio)', 'Nombre teofórico que significa ''Yahvé ha salvado''. Identifica a un príncipe de Judá que participó en la ceremonia de dedicación de los muros en tiempos de Nehemías (Neh 12:32) y al padre de Jezanías, un líder militar en la época de Jeremías (Jer 42:1; 43:2). El nombre refleja la teología de la liberación divina arraigada en la onomástica hebrea. Las traducciones conservan el nombre propio (Hosaías, Osaías) sin traducir su significado etimológico, respetando su función como identificador personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1959', 'spa', 'Grito, clamor, vitoreo; el grito sonoro de los pisadores de uva en la vendimia o el grito de guerra del enemigo.', 'Sustantivo que designa un grito comunitario fuerte, originalmente el clamor jubiloso que alzaban los que pisaban la uva durante la vendimia. Isaías 16:9-10 y Jeremías 48:33 lamentan el silenciamiento de este grito de lagar como señal de devastación. Sin embargo, la misma palabra también denota el grito de guerra amenazante del enemigo que se acerca. Jeremías 48:33 juega brillantemente con este doble sentido: ''el grito no es grito de vendimia,'' el sonido familiar de celebración ha sido reemplazado por el rugido aterrador de los invasores. En Jeremías 25:30, Yahvé mismo profiere un heidád como el de los pisadores de uva contra toda la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1961', 'spa', 'Ser, existir, llegar a ser, acontecer; verbo hebreo fundamental de existencia, cambio de estado, cópula y marcador narrativo.', 'Quizá el verbo más fundamental del hebreo bíblico, הָיָה carga sobre sí el peso de la existencia misma. Funciona como cópula (''era'', ''es'', ''será''), marca transiciones narrativas con el icónico וַיְהִי (''y aconteció''), y expresa un devenir transformador, como cuando el polvo de Egipto ''se convirtió'' en piojos (Éx 8:17). Su uso teológicamente más trascendente es la autorrevelación divina en la zarza ardiente: אֶהְיֶה אֲשֶׁר אֶהְיֶה — ''YO SOY EL QUE SOY'' (Éx 3:14), donde las traducciones multilingües muestran a los traductores luchando por captar la plenitud del Nombre divino intraducible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1964', 'spa', 'Templo o palacio: un edificio grandioso que sirve como santuario de Dios o como residencia real de un rey.', 'Templo o palacio: un edificio grandioso que sirve como santuario de Dios o como residencia real de un rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1965', 'spa', 'Un gran edificio: ya sea un templo (santuario sagrado) o un palacio (residencia real), del acadio ekallu', 'Un sustantivo arameo tomado del acadio ekallu (''casa grande''), que porta una ambigüedad productiva entre la arquitectura sagrada y la real. En el libro de Daniel, la misma palabra alterna entre el palacio real de Nabucodonosor (Dn 4:4, 29; 5:5) y el templo de Jerusalén cuyos vasos él saqueó (Dn 5:2-3). Esdras igualmente la emplea para el templo en reconstrucción (Esd 5:14-15; 6:5) y para la corte real cuya sal comen los funcionarios (Esd 4:14). La polisemia refleja la realidad del Antiguo Oriente Próximo, donde templos y palacios estaban arquitectónica y funcionalmente entrelazados como sedes de autoridad divina y humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1968', 'spa', 'Hemán — nombre propio que significa ''fiel'', músico-sabio levita y jefe de un gremio de música del templo.', 'Hemán — nombre propio que significa ''fiel'', músico-sabio levita y jefe de un gremio de música del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1969', 'spa', 'Hin; unidad hebrea de medida líquida (~6 litros), usada en las regulaciones sacrificiales para aceite, vino y agua', 'Hin; unidad hebrea de medida líquida (~6 litros), usada en las regulaciones sacrificiales para aceite, vino y agua');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1973', 'spa', 'Adelante, más allá — adverbio de extensión espacial o temporal desde un punto de referencia.', 'Adelante, más allá — adverbio de extensión espacial o temporal desde un punto de referencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1975', 'spa', 'Pronombre demostrativo arcaico que significa ''este'' o ''aquel,'' sinónimo poco frecuente de זֶה/הַזֶּה usado con sustantivos definidos.', 'Pronombre demostrativo raro y arcaico que funciona como sinónimo del hebreo común זֶה (''este'') o הַזֶּה (''este''). Aparece solo siete veces en la Biblia hebrea, siempre modificando un sustantivo ya marcado con el artículo definido. Su etimología lo vincula con el árabe alladhi (''el que/el cual''), combinando el artículo definido con el elemento demostrativo. El contexto determina si el referente es proximal (''este'') o distal (''aquel''): Jueces 6:20 señala una roca cercana, mientras que 1 Samuel 14:1 apunta al otro lado de un desfiladero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1979', 'spa', 'Marcha, procesión, camino; abarca desde una marcha sagrada hasta la conducta habitual o una caravana de viajeros.', 'Halikhah abarca todo el espectro del movimiento: desde la procesión solemne de Dios entrando en su santuario hasta los quehaceres cotidianos de una mujer virtuosa. En Salmo 68:24 se contemplan las procesiones de Dios al lugar santo, un espectáculo teofánico. Proverbios 31:27 emplea el plural para los «quehaceres» o la administración diaria del hogar, mientras que Habacuc 3:6 habla de los caminos eternos de Dios. En Job 6:19 las caravanas de Tema buscan agua desesperadamente, y el vocablo adquiere un sentido concreto y colectivo de viajeros en marcha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1980', 'spa', 'Ir, caminar, viajar; en sentido figurado, conducirse; en Hitpael, andar de un lado a otro; en Piel, caminar habitualmente', 'Halak es el verbo hebreo primario de locomoción, que abarca desde un simple viaje hasta la dirección moral de toda una vida. En el Qal significa ''ir, viajar, proseguir'', pero el pensamiento hebreo extendió con frecuencia el caminar al ámbito ético: andar en los estatutos de Dios, andar rectamente, andar en la maldad. El Hitpael añade una dimensión reflexiva e iterativa: pasear, recorrer o caminar íntimamente con Dios, como hicieron Enoc y Noé. El Piel intensifica la cualidad habitual, describiendo patrones sostenidos de movimiento o conducta. Con 513 apariciones en narrativa, ley, poesía y profecía, halak sustenta el discurso hebreo tanto sobre los viajes físicos como sobre el camino de la fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1981', 'spa', 'Caminar, andar; verbo arameo en Hafel/Pael', 'Verbo arameo que describe movimiento y conducta. Aparece en la visión de Daniel del horno de fuego, donde cuatro hombres ''caminan'' ilesos entre las llamas (Dan 3:25), y en el relato de Nabucodonosor ''paseándose'' por la terraza de su palacio (Dan 4:29) y luego ''andando con soberbia'' (Dan 4:37). El verbo puede denotar locomoción física o comportamiento ético, como en la expresión ''andar con orgullo''. Las traducciones reflejan ambos matices: movimiento literal y conducta moral figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1983', 'spa', 'Peaje, impuesto, tributo; término fiscal arameo', 'Término fiscal arameo que designa peajes o impuestos cobrados por la autoridad imperial. Aparece en la correspondencia de Esdras sobre las preocupaciones tributarias persas: los opositores advierten que Jerusalén no pagará ''peaje, tributo ni contribución'' (Esd 4:13, 20), y Artajerjes exime al personal del templo de tales gravámenes (Esd 7:24). Se trata de lenguaje administrativo propio de la burocracia aqueménida, que refleja el registro formal de la correspondencia oficial en arameo imperial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1984a', 'spa', 'Brillar, irradiar luz; dicho de los astros y del favor divino que ilumina a una persona.', 'Verbo poco frecuente (הָלַל I, distinto del común הָלַל II ''alabar'') que describe el brillo o destello de la luz. Job recuerda los días en que la lámpara de Dios ''brillaba'' sobre su cabeza (Job 29:3), imagen vívida del favor divino. En el Hifil describe la radiancia de los cuerpos celestes: el sol que resplandece (Job 31:26), el estornudo de Leviatán que despide luz (Job 41:18) y las estrellas que dejarán de alumbrar en el juicio (Is 13:10). Los cognados acadio ''elelu'' (ser brillante) y árabe ''halla'' (comenzar a brillar, de la luna nueva) confirman el sentido raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1984b', 'spa', 'Alabar, loar (a Dios); jactarse o gloriarse; ser alabado/digno de alabanza; enloquecer u obrar neciamente', 'La raíz detrás de la palabra más célebre del culto: Aleluya (''alabad a Yah''). En el tronco Piel ordena y celebra la alabanza doxológica dirigida a Dios, impregnando el Salterio desde el Salmo 22:23 hasta los Salmos del Halel (113-118). El Hitpael reflexivo vuelve el verbo hacia dentro: gloriarse o jactarse de algo, ya sea neciamente de uno mismo (Sal 52:1) o con razón en el Señor (Sal 34:2; 1 Cr 16:10). Una llamativa homofonía con הלל I produce el sentido ''enloquecer, enfurecerse'': Eclesiastés 7:7 advierte que la opresión ''enloquece al sabio''. El cognado árabe هَلَّ (''gritar'') conserva el sentido original de la raíz: clamar en voz alta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1984c', 'spa', 'Actuar como loco o fingir locura; jactarse con arrogancia; (Piel) enloquecer, volver necio', 'Actuar como loco o fingir locura; jactarse con arrogancia; (Piel) enloquecer, volver necio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1986', 'spa', 'Golpear, martillar o batir; por extensión, vencer o tambalear, como quien es derribado por el vino o la fuerza.', 'Verbo enérgico que evoca el golpe contundente de un martillo o mazo. Su aparición más vívida se halla en el Cántico de Débora, donde Jael clava una estaca en la sien de Sísara (Jue 5:26), y en el mismo poema los cascos de los caballos al galope golpean el suelo con estrépito (Jue 5:22). El cognado fenicio mahlam confirma la asociación de esta raíz con el acto de martillar. Más allá del golpe físico, la palabra se extiende al tambaleo de quienes son vencidos por el vino (Is 28:1) o al movimiento tumultuoso de una multitud (1 Sam 14:16), donde el impacto es metafórico pero igualmente desorientador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1988', 'spa', 'Acá, aquí — adverbio de lugar que indica movimiento hacia o presencia en la ubicación del hablante', 'Acá, aquí — adverbio de lugar que indica movimiento hacia o presencia en la ubicación del hablante');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1992', 'spa', 'Ellos, ellas, a ellos, de ellos, aquellos; pronombre personal 3.ª pl. con formas preposicionales (a/de/como/en ellos).', 'El pronombre personal masculino de tercera persona plural הֵמָּה (o הֵם) constituye uno de los elementos fundamentales del discurso hebreo, señalando a grupos de personas o cosas previamente mencionados. Más allá de su uso como sujeto independiente (''ellos''), se combina con preposiciones para expresar toda una gama de relaciones: dativo (''a ellos''), separativo (''de ellos''), comparativo (''como ellos'') y locativo (''en ellos''). Con el artículo definido se convierte en demostrativo ''aquellos'', especialmente en la fórmula ''en aquellos días''. Ocasionalmente sobrevive una variante arcaica femenina singular en textos poéticos como Job y Salmos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1993', 'spa', 'Murmurar, rugir, gemir, clamorear o estar en tumulto; se usa para mares embravecidos, corazones afligidos, multitudes ruidosas y agitación interior', 'Murmurar, rugir, gemir, clamorear o estar en tumulto; se usa para mares embravecidos, corazones afligidos, multitudes ruidosas y agitación interior');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1994', 'spa', 'himmo — pronombre arcaico de tercera persona masculino plural (''ellos, a ellos'') que aparece en Esdras y Daniel', 'himmo — pronombre arcaico de tercera persona masculino plural (''ellos, a ellos'') que aparece en Esdras y Daniel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1995a', 'spa', 'Sonido, estruendo, tumulto; multitud o muchedumbre de personas; abundancia o riqueza de posesiones.', 'Sonido, estruendo, tumulto; multitud o muchedumbre de personas; abundancia o riqueza de posesiones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1996', 'spa', 'Hamón-Gog, nombre profético de lugar que significa ''multitud de Gog''; el valle de sepultura en la visión escatológica de Ezequiel.', 'Nombre propio derivado del sustantivo común הָמוֹן (''multitud, tumulto''), empleado como topónimo en la profecía de Ezequiel sobre la derrota de Gog. El Valle de Hamón-Gog (''Multitud de Gog'') es donde serán enterradas las enormes hordas enemigas, y una ciudad llamada Hamoná se erigirá cerca como memorial. El español ''multitud de'' conserva la transparencia etimológica del nombre. Ezequiel eligió deliberadamente este topónimo para que la geografía misma proclamara la victoria de Dios sobre el enemigo abrumador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2000', 'spa', 'Confundir, derrotar o sembrar pánico (especialmente a enemigos en batalla bajo juicio divino); también empujar o trillar ruidosamente.', 'Confundir, derrotar o sembrar pánico (especialmente a enemigos en batalla bajo juicio divino); también empujar o trillar ruidosamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2001', 'spa', 'Amán: el oficial agagueo que tramó la destrucción de los judíos en el libro de Ester.', 'Amán: el oficial agagueo que tramó la destrucción de los judíos en el libro de Ester.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2002', 'spa', 'Cadena o collar; préstamo arameo del griego, referido a la cadena de oro de honor otorgada en la corte babilónica.', 'Sustantivo arameo que designa una cadena o collar, presente exclusivamente en Daniel 5 en relación con las recompensas prometidas y otorgadas a quien pudiera leer la escritura en la pared. El vocablo hamnika es un préstamo procedente en última instancia del griego μανιάκης (collar o torques), reflejo del vocabulario cosmopolita de la corte persa. Belsasar ofrece una cadena de oro, junto con vestiduras de púrpura y el rango de tercer gobernante, como premio por interpretar la inscripción. Se trata de una cadena para el cuello, marca de favor real más que simple adorno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2004', 'spa', 'Pronombre femenino plural de tercera persona ''ellas'' (hen), solo con preposiciones prefijadas: bahen, mehen, kahen', 'El pronombre femenino plural de tercera persona hen, que en el hebreo bíblico aparece únicamente regido por una preposición prefijada: bahen (''en/entre/con ellas''), mehen (''de/desde ellas'') y kahen (''como ellas''). Nunca aparece como pronombre sujeto independiente en el corpus bíblico, a diferencia de su contraparte masculina hem. Sus referentes son variados: las ciudades de las que Lot fue rescatado (Gn 19:29), los hijos de Raquel por los que ella trabajó (Gn 30:26), los utensilios de libación del tabernáculo (Éx 25:29; 37:16) y los incensarios ofrecidos con fuego extraño (Lv 10:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2005', 'spa', 'He aquí, mira. Interjección demostrativa que llama la atención sobre un hecho o situación; raramente ''si, acaso''.', 'Hen es una partícula presentativa enérgica que reclama la atención del oyente: ''¡Mira! ¡He aquí!'' Menos difundida que su cuasi sinónimo hinneh, hen tiende a aparecer en prosa, donde introduce un hecho conocido sobre el cual debe basarse una conclusión o una acción (Gn 3:22: ''He aquí, el hombre ha venido a ser como uno de nosotros''). Es especialmente frecuente en el Pentateuco y en los discursos de Job, donde posee un matiz más argumentativo y lógico que hinneh. El español ''he aquí'', el francés ''voici'' y el alemán ''siehe'' funcionan como marcadores presentativos, aunque ninguno capta del todo la fuerza particular de hen: ''dado este hecho, por lo tanto...''. En un único caso excepcional (Jer 2:10), hen funciona como partícula condicional con el sentido de ''si, acaso''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2006a', 'spa', 'Si, ya sea; o (en construcciones pareadas) — conjunción condicional aramea', 'La conjunción aramea הֵן funciona como la partícula condicional estándar en las porciones arameas de Esdras y Daniel, equivalente al hebreo אִם. Introduce cláusulas condicionales — ''si el rey lo tiene a bien'' (Esd 5:17), ''si no me declaráis el sueño'' (Dn 2:5) — y con לָא forma el condicional negado ''si no''. Cuando se duplica (הֵן ... הֵן), crea un par disyuntivo que significa ''sea ... o'', como en Esdras 7:26 al enumerar posibles castigos. Aunque pequeña y funcional, es un marcador clave del estrato lingüístico arameo en la Biblia hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2006b', 'spa', 'Por tanto, tal vez; conjuncion inferencial/condicional aramea', 'Conjuncion aramea que introduce una inferencia logica o una condicion tentativa. En Daniel, precede mandatos reales (''por tanto, decidme el sueno'', Dan 2:6, 9) y consejos (''por tanto, oh rey, acepta mi consejo'', Dan 4:27). Los lexicografos debaten si siempre significa ''por tanto'' o si a veces tiene el sentido de ''solo/tal vez''. Las traducciones reflejan ambos matices: el inferencial (por tanto, por eso) y el condicional (tal vez, quiza). La palabra senala transiciones retoricas y razonamientos en el discurso arameo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2007', 'spa', 'Ellas/estas (pronombre femenino plural); raramente ''aquí, he aquí'' como adverbio presentativo.', 'Ellas/estas (pronombre femenino plural); raramente ''aquí, he aquí'' como adverbio presentativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2008', 'spa', 'Acá, aquí; adverbio deíctico de lugar que significa ''a este lugar'', extendido temporalmente a ''ahora, hasta este momento''.', 'Acá, aquí; adverbio deíctico de lugar que significa ''a este lugar'', extendido temporalmente a ''ahora, hasta este momento''.');